'use client';

import AccountNav from '../../components/account-nav';
import { useEffect, useState } from 'react';
import { apiGet, apiPost, DEFAULT_TENANT_ID } from '../../lib/api-client';

export default function AccountWalletPage() {
  const [tenantId, setTenantId] = useState(DEFAULT_TENANT_ID);
  const [credits, setCredits] = useState(0);
  const [balance, setBalance] = useState(0);
  const [txCount, setTxCount] = useState(0);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);

  async function loadWallet(currentTenant: string) {
    const [usage, wallet] = await Promise.all([
      apiGet('/billing/usage', currentTenant),
      apiGet('/money-printers/nuxtron-bank/wallet', currentTenant),
    ]);
    setCredits(Number(usage.credit_balance || 0));
    const walletObj = (wallet.wallet as Record<string, unknown> | undefined) || {};
    setBalance(Number(walletObj.available_balance_usd || 0));
    setTxCount(((walletObj.recent_transactions as unknown[] | undefined) || []).length);
  }

  useEffect(() => {
    let active = true;
    setError('');
    loadWallet(tenantId).catch((ex) => {
      if (active) setError(ex instanceof Error ? ex.message : 'Failed to load wallet.');
    });
    return () => {
      active = false;
    };
  }, [tenantId]);

  async function addCredits() {
    setBusy(true);
    setError('');
    try {
      await apiPost('/billing/credits', { amount: 250, reason: 'wallet_topup_ui' }, tenantId);
      await loadWallet(tenantId);
    } catch (ex) {
      setError(ex instanceof Error ? ex.message : 'Could not add credits.');
    } finally {
      setBusy(false);
    }
  }

  return (
    <main className="account-shell">
      <AccountNav />
      <section className="card">
        <h1>Wallet For Credits</h1>
        <p className="muted">Use credits for generation workloads and AI processing units.</p>
        <label className="auth-form" style={{ maxWidth: 360 }}>
          <span>Tenant ID</span>
          <input value={tenantId} onChange={(e) => setTenantId(e.target.value)} />
        </label>
        {error ? <p className="auth-errors">{error}</p> : null}
        <div className="grid dashboard-kpis">
          <article className="card kpi-card">
            <p className="kpi-label">Available Credits</p>
            <h3>{credits}</h3>
          </article>
          <article className="card kpi-card">
            <p className="kpi-label">Bank Wallet Balance (USD)</p>
            <h3>{balance.toFixed(2)}</h3>
          </article>
          <article className="card kpi-card">
            <p className="kpi-label">Recent Transactions</p>
            <h3>{txCount}</h3>
          </article>
        </div>
        <button onClick={addCredits} disabled={busy}>
          {busy ? 'Adding Credits...' : 'Add Credits'}
        </button>
      </section>
    </main>
  );
}

