'use client';

import { useState } from 'react';

type Tab = 'images' | 'videos' | 'voice' | 'text';

const TABS: { key: Tab; label: string; emoji: string }[] = [
  { key: 'images', label: 'Images', emoji: '­ƒû╝' },
  { key: 'videos', label: 'Videos', emoji: '­ƒÄ¼' },
  { key: 'voice', label: 'Voice', emoji: '­ƒÄÖ' },
  { key: 'text', label: 'Text', emoji: '­ƒÆ¼' },
];

type ModelStat = { name: string; pct: number; count: string; color: string };
type PerfStat = { name: string; ms: number };
type TabData = {
  color: string;
  totalToday: string;
  delta: string;
  successRate: string;
  avgLatency: string;
  activeModels: number;
  models: ModelStat[];
  themes: string[];
  timeSeries: number[];
  perf: PerfStat[];
  recentActivity: string[];
};

const DATA: Record<Tab, TabData> = {
  images: {
    color: '#1bc7ff',
    totalToday: '0',
    delta: '+0%',
    successRate: 'ÔÇö',
    avgLatency: 'ÔÇö',
    activeModels: 0,
    models: [],
    themes: [],
    timeSeries: [],
    perf: [],
    recentActivity: [],
  },
  videos: {
    color: '#a78bfa',
    totalToday: '0',
    delta: '+0%',
    successRate: 'ÔÇö',
    avgLatency: 'ÔÇö',
    activeModels: 0,
    models: [],
    themes: [],
    timeSeries: [],
    perf: [],
    recentActivity: [],
  },
  voice: {
    color: '#26d78e',
    totalToday: '0',
    delta: '+0%',
    successRate: 'ÔÇö',
    avgLatency: 'ÔÇö',
    activeModels: 0,
    models: [],
    themes: [],
    timeSeries: [],
    perf: [],
    recentActivity: [],
  },
  text: {
    color: '#f59e0b',
    totalToday: '0',
    delta: '+0%',
    successRate: 'ÔÇö',
    avgLatency: 'ÔÇö',
    activeModels: 0,
    models: [],
    themes: [],
    timeSeries: [],
    perf: [],
    recentActivity: [],
  },
};

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

// ÔöÇÔöÇÔöÇ SVG Donut Chart ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
function DonutChart({ models }: { models: ModelStat[] }) {
  const R = 54;
  const C = 2 * Math.PI * R;
  const GAP = 2.5;
  let cumPct = 0;

  return (
    <svg width="140" height="140" viewBox="0 0 140 140" aria-hidden="true">
      {/* Background ring */}
      <circle cx="70" cy="70" r={R} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="18" />
      {models.map((m) => {
        const segLen = Math.max(0, (m.pct / 100) * C - GAP);
        const rotation = (cumPct / 100) * 360 - 90;
        cumPct += m.pct;
        return (
          <circle
            key={m.name}
            cx="70"
            cy="70"
            r={R}
            fill="none"
            stroke={m.color}
            strokeWidth="18"
            strokeDasharray={`${segLen} ${C}`}
            strokeLinecap="butt"
            style={{ transform: `rotate(${rotation}deg)`, transformOrigin: '70px 70px' }}
          />
        );
      })}
      {/* Center label */}
      <text x="70" y="63" textAnchor="middle" fill="var(--text)" fontSize="20" fontWeight="700">
        {models.length}
      </text>
      <text x="70" y="78" textAnchor="middle" fill="var(--muted)" fontSize="10">
        models
      </text>
    </svg>
  );
}

// ÔöÇÔöÇÔöÇ SVG Line Chart ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
function LineChart({ data, color }: { data: number[]; color: string }) {
  const VW = 560;
  const H = 80;
  const padX = 6;
  const padY = 8;
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;

  const sx = (i: number) => padX + (i / (data.length - 1)) * (VW - padX * 2);
  const sy = (v: number) => padY + (1 - (v - min) / range) * (H - padY * 2);

  const points = data.map((v, i) => `${sx(i)},${sy(v)}`).join(' ');
  const areaPoints = `${sx(0)},${H} ${points} ${sx(data.length - 1)},${H}`;
  const gradId = `lg${color.replace('#', '')}`;
  const peakIdx = data.indexOf(Math.max(...data));

  return (
    <svg width="100%" height={H} viewBox={`0 0 ${VW} ${H}`} preserveAspectRatio="none" aria-hidden="true">
      <defs>
        <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity="0.28" />
          <stop offset="100%" stopColor={color} stopOpacity="0" />
        </linearGradient>
      </defs>
      {/* Grid lines */}
      {[0.25, 0.5, 0.75].map((t) => (
        <line
          key={t}
          x1={padX}
          y1={padY + (1 - t) * (H - padY * 2)}
          x2={VW - padX}
          y2={padY + (1 - t) * (H - padY * 2)}
          stroke="rgba(255,255,255,0.05)"
          strokeWidth="1"
        />
      ))}
      <polygon points={areaPoints} fill={`url(#${gradId})`} />
      <polyline
        points={points}
        fill="none"
        stroke={color}
        strokeWidth="2.4"
        strokeLinejoin="round"
        strokeLinecap="round"
      />
      {/* Peak marker */}
      <circle cx={sx(peakIdx)} cy={sy(data[peakIdx])} r="5" fill={color} />
      <circle cx={sx(peakIdx)} cy={sy(data[peakIdx])} r="9" fill={color} fillOpacity="0.2" />
      {/* Latest dot */}
      <circle cx={sx(data.length - 1)} cy={sy(data[data.length - 1])} r="3.5" fill={color} />
    </svg>
  );
}

// ÔöÇÔöÇÔöÇ SVG Horizontal Bar Chart ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
function BarChart({ data, color }: { data: PerfStat[]; color: string }) {
  const VW = 320;
  const barH = 14;
  const gap = 12;
  const labelW = 72;
  const valueW = 36;
  const maxMs = Math.max(...data.map((d) => d.ms));
  const totalH = data.length * (barH + gap) - gap;
  const fmtMs = (ms: number) => (ms >= 1000 ? `${(ms / 1000).toFixed(1)}s` : `${ms}ms`);

  return (
    <svg width="100%" height={totalH} viewBox={`0 0 ${VW} ${totalH}`} aria-hidden="true">
      {data.map((d, i) => {
        const bw = Math.max(6, (d.ms / maxMs) * (VW - labelW - valueW - 8));
        const y = i * (barH + gap);
        return (
          <g key={d.name}>
            <text x="0" y={y + barH - 2} fill="var(--muted)" fontSize="11">
              {d.name}
            </text>
            {/* Track */}
            <rect x={labelW} y={y} width={VW - labelW - valueW} height={barH} rx="4" fill="rgba(255,255,255,0.05)" />
            {/* Fill */}
            <rect x={labelW} y={y} width={bw} height={barH} rx="4" fill={color} opacity="0.8" />
            <text x={VW} y={y + barH - 2} textAnchor="end" fill="var(--muted)" fontSize="10">
              {fmtMs(d.ms)}
            </text>
          </g>
        );
      })}
    </svg>
  );
}

// ÔöÇÔöÇÔöÇ Mini sparkline for stat cards ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
function Sparkline({ data, color }: { data: number[]; color: string }) {
  const W = 60;
  const H = 24;
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;
  const sx = (i: number) => (i / (data.length - 1)) * W;
  const sy = (v: number) => H - ((v - min) / range) * H * 0.8 - H * 0.1;
  const points = data.map((v, i) => `${sx(i)},${sy(v)}`).join(' ');

  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} aria-hidden="true">
      <polyline
        points={points}
        fill="none"
        stroke={color}
        strokeWidth="1.5"
        strokeLinejoin="round"
        strokeLinecap="round"
        opacity="0.7"
      />
    </svg>
  );
}

// ÔöÇÔöÇÔöÇ Page ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
