            </article>
            <article className="card kpi-card">
              <p className="kpi-label">Avg ROI</p>
              <h3>{analytics.kpi.avg_roi.toFixed(3)}</h3>
            </article>
            <article className="card kpi-card">
              <p className="kpi-label">Avg Latency</p>
