              <p className="kpi-label">Cost</p>
              <h3>${analytics.kpi.total_estimated_cost.toFixed(4)}</h3>
            </article>
            <article className="card kpi-card">
              <p className="kpi-label">Value</p>
              <h3>${analytics.kpi.total_estimated_value.toFixed(4)}</h3>
            </article>
            <article className="card kpi-card">
              <p className="kpi-label">Tenant Block</p>
              <h3 style={{ color: analytics.kpi.is_blocked ? '#ef4444' : '#10b981' }}>
                {analytics.kpi.is_blocked ? 'Blocked' : 'Healthy'}
              </h3>
            </article>
          </section>

          <ChartCard
            title="Provider Call Volume"
            subtitle="Request share by provider with average ROI attached to each bar."
          >
            <BarChart data={providerChart} emptyLabel="No provider activity in the selected window." />
          </ChartCard>

          <ChartCard title="ROI Trend" subtitle="Last 12 AI gateway events for the selected tenant.">
            <LineChart
              data={roiTimeline}
              emptyLabel="No ROI points available yet."
              stroke="#22c55e"
              formatValue={(value) => value.toFixed(3)}
            />
          </ChartCard>

          <ChartCard title="Latency Trend" subtitle="End-to-end latency captured from the secured AI gateway path.">
            <LineChart
              data={latencyTimeline}
              emptyLabel="No latency points available yet."
              stroke="#0ea5e9"
              formatValue={(value) => `${value.toFixed(0)} ms`}
            />
          </ChartCard>

          <section className="grid dashboard-kpis" style={{ marginTop: 20 }}>
            <article className="card kpi-card">
              <p className="kpi-label">Rotate Provider Key</p>
              <select
                value={rotateProvider}
                onChange={(e) => setRotateProvider(e.target.value as 'openai' | 'anthropic')}
