'use client';

import { useEffect, useState } from 'react';
import { apiGet, apiSend, DEFAULT_TENANT_ID } from '../lib/platform-api';

type Plan = { id: string; display: string; price_monthly: number; price_annual: number; ai_credits: number };

type Usage = { credit_balance: number; current_plan: string; plan_display: string };

type Invoice = { id: number; amount: number; currency: string; status: string; created_at: string };

export default function BillingPage() {
  const [tenantId] = useState(DEFAULT_TENANT_ID);
  const [plans, setPlans] = useState<Plan[]>([]);
  const [usage, setUsage] = useState<Usage | null>(null);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [planId, setPlanId] = useState('pro');
  const [cycle, setCycle] = useState<'monthly' | 'annual'>('monthly');
  const [credits, setCredits] = useState('1000');
  const [error, setError] = useState('');
  const [status, setStatus] = useState('');

  async function load() {
    try {
      setError('');
      const [plansRes, usageRes, invoicesRes] = await Promise.all([
        apiGet<{ plans: Plan[] }>('/billing/plans', tenantId),
        apiGet<Usage & { status: string }>('/billing/usage', tenantId),
        apiGet<{ invoices: Invoice[] }>('/billing/invoices', tenantId),
      ]);
      setPlans(plansRes.plans ?? []);
      setUsage(usageRes);
      setInvoices(invoicesRes.invoices ?? []);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load billing');
    }
  }

  useEffect(() => {
    void load();
  }, []);

  async function subscribe() {
    try {
      await apiSend(
        '/billing/subscribe',
        'POST',
        {
          plan_id: planId,
          billing_cycle: cycle,
          payment_method_id: 'manual-dev',
        },
        tenantId
      );
      setStatus('Subscription updated.');
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Subscribe failed');
    }
  }

  async function addCredits() {
    try {
      await apiSend(
        '/billing/credits',
        'POST',
        {
          amount: Number.parseInt(credits, 10) || 0,
          reason: 'manual_topup',
        },
        tenantId
      );
      setStatus('Credits added.');
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Credit add failed');
    }
  }

  const card = { background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 16 };
  const input = {
    width: '100%',
    padding: '8px 10px',
    borderRadius: 8,
    border: '1px solid var(--line)',
    background: 'var(--bg)',
    color: 'var(--text)',
    marginBottom: 8,
  };

  return (
    <main style={{ minHeight: '100vh', background: 'var(--bg)', color: 'var(--text)', padding: 24 }}>
      <div style={{ maxWidth: 1100, margin: '0 auto' }}>
        <h1 style={{ marginTop: 0 }}>Billing Center</h1>
        <p style={{ color: 'var(--muted)' }}>Plan subscriptions, credits, and invoice audit trail.</p>
        {(error || status) && (
          <div style={{ ...card, marginBottom: 10, color: error ? '#f87171' : '#34d399' }}>{error || status}</div>
        )}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
            gap: 10,
            marginBottom: 10,
          }}
        >
          <div style={card}>
            <div style={{ color: 'var(--muted)', fontSize: 12 }}>Current Plan</div>
            <div style={{ fontSize: 24, fontWeight: 700 }}>{usage?.plan_display ?? '-'}</div>
          </div>
          <div style={card}>
            <div style={{ color: 'var(--muted)', fontSize: 12 }}>Plan ID</div>
            <div style={{ fontSize: 24, fontWeight: 700 }}>{usage?.current_plan ?? '-'}</div>
          </div>
          <div style={card}>
            <div style={{ color: 'var(--muted)', fontSize: 12 }}>AI Credits</div>
            <div style={{ fontSize: 24, fontWeight: 700 }}>{usage?.credit_balance ?? 0}</div>
          </div>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.3fr', gap: 10 }}>
          <section style={card}>
            <h3 style={{ marginTop: 0 }}>Subscription Actions</h3>
            <select value={planId} onChange={(e) => setPlanId(e.target.value)} style={input}>
              {plans.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.display} ({p.id})
                </option>
              ))}
            </select>
            <select value={cycle} onChange={(e) => setCycle(e.target.value as 'monthly' | 'annual')} style={input}>
              <option value="monthly">Monthly</option>
              <option value="annual">Annual</option>
            </select>
            <button
              onClick={() => void subscribe()}
              style={{
                padding: '8px 12px',
                border: 'none',
                borderRadius: 8,
                background: 'var(--brand)',
                color: '#00101e',
                fontWeight: 700,
                marginBottom: 10,
              }}
            >
              Subscribe / Switch
            </button>
            <input value={credits} onChange={(e) => setCredits(e.target.value)} style={input} type="number" min={1} />
            <button
              onClick={() => void addCredits()}
              style={{
                padding: '8px 12px',
                border: '1px solid var(--line)',
                borderRadius: 8,
                background: 'transparent',
                color: 'var(--text)',
              }}
            >
              Add Credits
            </button>
          </section>
          <section style={card}>
            <h3 style={{ marginTop: 0 }}>Plan Catalog</h3>
            {plans.map((p) => (
              <div key={p.id} style={{ borderBottom: '1px solid var(--line)', padding: '8px 0' }}>
                <div style={{ fontWeight: 700 }}>{p.display}</div>
                <div style={{ fontSize: 12, color: 'var(--muted)' }}>
                  ${p.price_monthly}/mo ┬À ${p.price_annual}/yr-month equiv ┬À {p.ai_credits} credits
                </div>
              </div>
            ))}
          </section>
        </div>
        <section style={{ ...card, marginTop: 10 }}>
          <h3 style={{ marginTop: 0 }}>Invoices ({invoices.length})</h3>
          {invoices.map((inv) => (
            <div key={inv.id} style={{ borderBottom: '1px solid var(--line)', padding: '8px 0' }}>
              <div style={{ fontWeight: 700 }}>
                Invoice #{inv.id} - {inv.status}
              </div>
              <div style={{ fontSize: 12, color: 'var(--muted)' }}>
                {inv.amount} {inv.currency} ┬À {new Date(inv.created_at).toLocaleString()}
              </div>
            </div>
          ))}
        </section>
      </div>
    </main>
  );
}

