            {exports.map((item) => (
              <div
                key={item.id}
                style={{ borderBottom: '1px solid var(--line)', padding: '6px 0', fontSize: 12, color: 'var(--muted)' }}
              >
                #{item.id} ┬À {item.provider_alias || item.provider} ┬À {item.export_type} ┬À {item.period_label} ┬À{' '}
                {item.status}
