'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { apiGet, DEFAULT_TENANT_ID } from '../lib/platform-api';

// ÔöÇÔöÇÔöÇ Types ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

type IRAEvent = {
  id: number;
  event_type: string;
  payload: Record<string, unknown>;
  created_at: string;
};

type IRASession = {
  id: number;
  role: string;
  channel: string;
  user_message: string;
  created_at: string;
};

type IRAActionSnapshot = {
  id: number;
  target: string;
  command: string;
  confidence: number;
  rollback_enabled: boolean;
  created_at: string;
};

type MonitorData = {
  recent_events: IRAEvent[];
  recent_sessions: IRASession[];
  recent_snapshots: IRAActionSnapshot[];
  stats: {
    avg_confidence: number;
    total_chats: number;
    total_actions: number;
    failed_actions: number;
    total_cost_pence: number;
    total_cost_gbp: number;
  };
};

type PerformanceByType = {
  count: number;
  success_rate: number;
  failure_rate: number;
  avg_confidence: number;
  avg_latency_ms: number;
};

type PerformanceData = {
  total_data_points: number;
  overall_success_rate: number;
  overall_avg_confidence: number;
  by_action_type: Record<string, PerformanceByType>;
  recent: Array<{
    id: number;
    action_type: string;
    latency_ms: number;
    confidence: number;
    outcome: string;
    created_at: string;
  }>;
};

type ABVariantStats = {
  impressions: number;
  success_rate: number;
  avg_value: number;
};

type ABTest = {
  id: number;
  name: string;
  description: string;
  variants: string[];
  metric: string;
  status: string;
  created_at: string;
  analysis: {
    winner: string | null;
    confidence: number;
    by_variant: Record<string, ABVariantStats>;
  };
};

type ABTestsData = {
  total: number;
  tests: ABTest[];
};

type Tab = 'overview' | 'performance' | 'abtests' | 'events';

// ÔöÇÔöÇÔöÇ Helpers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

function formatTime(iso: string) {
  try { return new Date(iso).toLocaleTimeString(); } catch { return iso; }
}

function confidenceBadge(c: number) {
  if (c >= 0.8) return 'bg-green-500/20 text-green-300';
  if (c >= 0.6) return 'bg-yellow-500/20 text-yellow-300';
  return 'bg-red-500/20 text-red-300';
}

function outcomeBadge(o: string) {
  if (o === 'success') return 'bg-green-500/20 text-green-300';
  if (o === 'failure') return 'bg-red-500/20 text-red-300';
  return 'bg-slate-600 text-slate-300';
}

function pct(n: number) { return `${(n * 100).toFixed(1)}%`; }

// ÔöÇÔöÇÔöÇ Component ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

export default function IRAMonitor() {
  const [monitor, setMonitor] = useState<MonitorData | null>(null);
  const [perf, setPerf] = useState<PerformanceData | null>(null);
  const [abTests, setAbTests] = useState<ABTestsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [tab, setTab] = useState<Tab>('overview');
  const [filter, setFilter] = useState<'all' | 'high' | 'low'>('all');
  const [lastRefreshLabel, setLastRefreshLabel] = useState('pending');

  const fetchAll = async () => {
    try {
      const [monitorData, performanceData, abTestsData] = await Promise.all([
        apiGet<MonitorData>('/ira/monitor', DEFAULT_TENANT_ID),
        apiGet<PerformanceData>('/ira/performance', DEFAULT_TENANT_ID),
        apiGet<ABTestsData>('/ira/ab-tests', DEFAULT_TENANT_ID),
      ]);

      setMonitor(monitorData);
      setPerf(performanceData);
      setAbTests(abTestsData);
      setError(null);
      setLastRefreshLabel(new Date().toLocaleTimeString());
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Network error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAll();
    const interval = setInterval(fetchAll, 5000);
    return () => clearInterval(interval);
  }, []);  

  const filteredSnapshots = (monitor?.recent_snapshots ?? []).filter((s) => {
    if (filter === 'high') return s.confidence >= 0.75;
    if (filter === 'low') return s.confidence < 0.5;
    return true;
  });

  const tabs: { id: Tab; label: string }[] = [
    { id: 'overview', label: 'Overview' },
    { id: 'performance', label: 'Performance' },
    { id: 'abtests', label: `A/B Tests${abTests ? ` (${abTests.total})` : ''}` },
    { id: 'events', label: 'Events' },
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 to-slate-800 p-6">
      <div className="max-w-7xl mx-auto">

        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-3xl font-bold text-white">IRA Monitor</h1>
            <p className="text-slate-400 text-sm mt-1">
              Real-time autonomous agent ┬À refreshed {lastRefreshLabel}
            </p>
          </div>
          <div className="flex items-center gap-3">
            <button
              onClick={() => { setLoading(true); void fetchAll(); }}
              className="px-3 py-1.5 bg-slate-700 hover:bg-slate-600 text-slate-300 text-sm rounded-lg transition"
            >
              Ôå╗ Refresh
            </button>
            <Link
              href="/dashboard"
              className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-lg transition"
            >
              ÔåÉ Dashboard
            </Link>
          </div>
        </div>

        {/* Stat Cards */}
        {monitor && (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3 mb-6">
            {([
              { label: 'Avg Confidence', value: pct(monitor.stats.avg_confidence), color: 'text-white' },
              { label: 'Chat Sessions', value: monitor.stats.total_chats, color: 'text-white' },
              { label: 'Actions Run', value: monitor.stats.total_actions, color: 'text-white' },
              { label: 'Failed', value: monitor.stats.failed_actions, color: 'text-red-400' },
              { label: 'Total Cost', value: `\u00a3${monitor.stats.total_cost_gbp.toFixed(4)}`, sub: `${monitor.stats.total_cost_pence.toFixed(2)}p`, color: 'text-emerald-400' },
              perf
                ? { label: 'Overall Success', value: pct(perf.overall_success_rate), color: 'text-cyan-400' }
                : { label: 'Success Rate', value: '\u2014', color: 'text-slate-400' },
            ] as Array<{ label: string; value: string | number; sub?: string; color: string }>).map((s, i) => (
              <div key={`item-${i}`} className="bg-slate-700/50 backdrop-blur border border-slate-600 rounded-lg p-4">
                <p className="text-slate-400 text-xs mb-1">{s.label}</p>
                <p className={`text-xl font-bold ${s.color}`}>{String(s.value)}</p>
                {s.sub && <p className="text-slate-500 text-xs mt-0.5">{s.sub}</p>}
              </div>
            ))}
          </div>
        )}

        {/* Loading */}
        {loading && (
          <div className="bg-slate-700/50 border border-slate-600 rounded-lg p-10 text-center">
            <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-white mb-3" />
            <p className="text-slate-300">Loading IRA activityÔÇª</p>
          </div>
        )}

        {/* Error */}
        {error && (
          <div className="bg-red-500/10 border border-red-500 rounded-lg p-4 mb-6">
            <p className="text-red-400 text-sm">ÔÜá {error}</p>
          </div>
        )}

        {/* Tabs */}
        {monitor && !loading && (
          <>
            <div className="flex gap-1 mb-5 bg-slate-800 rounded-lg p-1 w-fit">
              {tabs.map((t) => (
                <button
                  key={t.id}
                  onClick={() => setTab(t.id)}
                  className={`px-4 py-2 rounded-md text-sm font-medium transition ${
                    tab === t.id
                      ? 'bg-blue-600 text-white shadow'
                      : 'text-slate-400 hover:text-white hover:bg-slate-700'
                  }`}
                >
                  {t.label}
                </button>
              ))}
            </div>

            {/* OVERVIEW */}
            {tab === 'overview' && (
              <div className="space-y-5">
                <section className="bg-slate-700/50 border border-slate-600 rounded-lg overflow-hidden">
                  <div className="px-6 py-4 border-b border-slate-600 flex justify-between items-center">
                    <h2 className="font-bold text-white">Action Snapshots</h2>
                    <div className="flex gap-2">
                      {(['all', 'high', 'low'] as const).map((f) => (
                        <button
                          key={f}
                          onClick={() => setFilter(f)}
                          className={`px-3 py-1 rounded text-xs transition ${
                            filter === f
                              ? f === 'all' ? 'bg-blue-600 text-white' : f === 'high' ? 'bg-green-600 text-white' : 'bg-red-600 text-white'
                              : 'bg-slate-600 text-slate-300 hover:bg-slate-500'
                          }`}
                        >
                          {f === 'all' ? 'All' : f === 'high' ? '>=75%' : '<50%'}
                        </button>
                      ))}
                    </div>
                  </div>
                  {filteredSnapshots.length === 0 ? (
                    <p className="p-6 text-slate-400 text-sm text-center">No snapshots yet.</p>
                  ) : (
                    <div className="overflow-x-auto">
                      <table className="w-full text-sm">
                        <thead className="bg-slate-800 text-slate-400 text-xs uppercase">
                          <tr>
                            <th className="px-5 py-3 text-left">Target</th>
                            <th className="px-5 py-3 text-left">Command</th>
                            <th className="px-5 py-3 text-center">Confidence</th>
                            <th className="px-5 py-3 text-center">Rollback</th>
                            <th className="px-5 py-3 text-left">Time</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-700">
                          {filteredSnapshots.slice(0, 12).map((s) => (
                            <tr key={s.id} className="hover:bg-slate-700/60 transition">
                              <td className="px-5 py-3"><span className="px-2 py-0.5 bg-purple-500/20 text-purple-300 rounded text-xs font-mono">{s.target}</span></td>
                              <td className="px-5 py-3 text-slate-300 font-mono text-xs">{s.command}</td>
