type Json = Record<string, unknown>;

type IraStatus = {
  autonomy?: Json;
  connectors?: Json[];
  finance_health?: Json;
  risk_signal?: Json;
  recent_events?: Json[];
};

type CrmSyncStatus = {
  enabled?: boolean;
  interval_seconds?: number;
  last_sync_at?: string | null;
  events_processed_24h?: number;
};

type CrmBackupOps = {
  schedule_health?: string;
  next_runs?: { incremental_at?: string; full_at?: string };
  latest_incremental?: { completed_at?: string | null } | null;
  latest_full?: { completed_at?: string | null } | null;
};

type IraMlOverview = {
  summary?: Json;
  documents?: Json[];
  jobs?: Json[];
  models?: Json[];
};

type IraMemoryOverviewResponse = {
  memory?: Json;
};

type IraAgentFrameworksResponse = {
  frameworks?: Json;
  auto_policy?: Json;
  brain?: Json;
};

type IraFrontierStackResponse = {
  frontier?: Json;
  readiness?: Json;
  env_template?: Json;
  god_stack_example?: Json;
};

const EMPTY_STATUS: IraStatus = {};

function asNumber(value: unknown, fallback = 0): number {
  return typeof value === 'number' ? value : fallback;
}

function asString(value: unknown, fallback = ''): string {
  return typeof value === 'string' ? value : fallback;
}

function asJson(value: unknown): Json {
  return value && typeof value === 'object' && !Array.isArray(value) ? (value as Json) : {};
}

function getFrontierReadinessColor(state: string): string {
  if (state === 'high') return '#16a34a';
  if (state === 'medium') return '#d97706';
  return '#dc2626';
}

type IraMemorySectionProps = {
  loading: boolean;
  memorySummary: Json;
  memoryProviders: Json;
  memoryType: string;
  setMemoryType: (value: string) => void;
  memoryKey: string;
  setMemoryKey: (value: string) => void;
  memoryPayload: string;
  setMemoryPayload: (value: string) => void;
  onUpsert: () => void | Promise<void>;
  structuredMemoryResult: Json;
  shortTermMessages: Json[];
  structuredMemoryRecords: Json[];
};

function IraMemorySection({
  loading,
  memorySummary,
  memoryProviders,
  memoryType,
  setMemoryType,
  memoryKey,
  setMemoryKey,
  memoryPayload,
  setMemoryPayload,
  onUpsert,
  structuredMemoryResult,
  shortTermMessages,
  structuredMemoryRecords,
}: Readonly<IraMemorySectionProps>) {
  return (
    <section className="card" style={{ marginTop: 18 }}>
      <h3>Autonomy Memory System</h3>
      <p className="muted">
        Short-term conversation memory, long-term vector memory, and structured user or task memory for autonomous IRA
        behavior. Redis handles fast context, Supabase Postgres handles structured persistence, and the vector layer
        can target Supabase embeddings, Pinecone, or Weaviate without duplicating the in-app knowledge store.
      </p>

      <div className="grid dashboard-kpis" style={{ marginTop: 12 }}>
        <article className="card kpi-card">
          <p className="kpi-label">Short-Term Messages</p>
          <h3>{asNumber(memorySummary.short_term_messages, 0)}</h3>
        </article>
        <article className="card kpi-card">
          <p className="kpi-label">Structured Records</p>
          <h3>{asNumber(memorySummary.structured_records, 0)}</h3>
        </article>
        <article className="card kpi-card">
          <p className="kpi-label">Long-Term Documents</p>
          <h3>{asNumber(memorySummary.long_term_documents, 0)}</h3>
        </article>
        <article className="card kpi-card">
          <p className="kpi-label">Long-Term Chunks</p>
          <h3>{asNumber(memorySummary.long_term_chunks, 0)}</h3>
        </article>
        <article className="card kpi-card">
          <p className="kpi-label">Short-Term Backend</p>
          <h3>{asString(memorySummary.active_short_term_backend, 'in_memory')}</h3>
        </article>
        <article className="card kpi-card">
          <p className="kpi-label">Long-Term Backend</p>
          <h3>{asString(memorySummary.active_long_term_backend, 'in_memory')}</h3>
        </article>
      </div>

      <h4 style={{ marginTop: 16 }}>Provider Status</h4>
      <pre>{JSON.stringify(memoryProviders, null, 2)}</pre>

      <div className="workspace-io-grid" style={{ marginTop: 12 }}>
        <div>
          <label htmlFor="ira-memory-type">Structured Memory Type</label>
          <select id="ira-memory-type" value={memoryType} onChange={(event) => setMemoryType(event.target.value)}>
            <option value="user_profile">User Profile</option>
            <option value="task">Task</option>
            <option value="preference">Preference</option>
            <option value="workflow_state">Workflow State</option>
          </select>
          <label htmlFor="ira-memory-key">Memory Key</label>
          <input id="ira-memory-key" value={memoryKey} onChange={(event) => setMemoryKey(event.target.value)} />
          <label htmlFor="ira-memory-payload">JSON Payload</label>
          <textarea
            id="ira-memory-payload"
            rows={8}
            value={memoryPayload}
            onChange={(event) => setMemoryPayload(event.target.value)}
          />
          <div className="workspace-actions">
            <button onClick={onUpsert} disabled={loading}>
              Upsert Structured Memory
            </button>
          </div>
          <pre>{JSON.stringify(structuredMemoryResult, null, 2)}</pre>
        </div>

        <div>
          <h4>Recent Short-Term Memory</h4>
          <pre>{JSON.stringify(shortTermMessages, null, 2)}</pre>
          <h4 style={{ marginTop: 16 }}>Structured Memory Records</h4>
          <pre>{JSON.stringify(structuredMemoryRecords, null, 2)}</pre>
        </div>
      </div>
    </section>
  );
}

