            <input
              id="quality-accuracy"
              type="number"
              min={0}
              max={100}
              value={accuracy}
              onChange={(e) => setAccuracy(Number(e.target.value))}
              style={{
                width: '100%',
                padding: '0.4rem 0.6rem',
                borderRadius: 6,
                border: '1px solid #333',
                background: '#111',
                color: '#fff',
              }}
            />
          </div>
          <div>
            <label htmlFor="quality-safety" style={{ fontSize: '0.78rem', color: '#888' }}>
              Safety (0-100)
