          <thead>
            <tr style={{ borderBottom: '1px solid #333' }}>
              {['Action ID', 'Score', 'Band', 'Accuracy', 'Safety', 'Revenue ┬ú', 'Date'].map((h) => (
                <th key={h} style={{ textAlign: 'left', padding: '0.4rem 0.6rem', color: '#888' }}>
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {qualityScores.slice(0, 20).map((q, idx) => {
              const qs = q as Json;
              const band = asString(qs.band, 'poor');
              return (
                <tr key={`${asString(qs.id)}-${idx}`} style={{ borderBottom: '1px solid #1a1a1a' }}>
                  <td style={{ padding: '0.4rem 0.6rem', fontFamily: 'monospace', fontSize: '0.75rem', color: '#888' }}>
                    {asString(qs.action_id).slice(0, 12)}ÔÇª
                  </td>
                  <td style={{ padding: '0.4rem 0.6rem', fontWeight: 700, color: BAND_COLOR[band] }}>
                    {asNumber(qs.score)}
                  </td>
                  <td style={{ padding: '0.4rem 0.6rem', color: BAND_COLOR[band], textTransform: 'capitalize' }}>
                    {band}
                  </td>
                  <td style={{ padding: '0.4rem 0.6rem' }}>{asNumber(qs.accuracy)}</td>
                  <td style={{ padding: '0.4rem 0.6rem' }}>{asNumber(qs.safety)}</td>
                  <td style={{ padding: '0.4rem 0.6rem' }}>┬ú{asNumber(qs.revenue_impact_gbp).toFixed(2)}</td>
                  <td style={{ padding: '0.4rem 0.6rem', color: '#888', fontSize: '0.78rem' }}>
                    {asString(qs.created_at).slice(0, 10)}
                  </td>
                </tr>
              );
            })}
            {qualityScores.length === 0 && (
              <tr>
                <td colSpan={7} style={{ padding: '1rem', color: '#888', textAlign: 'center' }}>
                  No quality scores yet
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </section>

      {/* Pending attribution */}
      {pendingActions.length > 0 && (
        <section>
          <h2 style={{ fontSize: '1.1rem', fontWeight: 600, marginBottom: '0.75rem' }}>
            Pending Attribution ({pendingActions.length})
          </h2>
          <p style={{ color: '#888', fontSize: '0.85rem', marginBottom: '0.75rem' }}>
            These actions have no attributed outcome yet. Use <code>/outcome/outcomes</code> to close them.
          </p>
          <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
            {pendingActions.slice(0, 10).map((a, idx) => {
              const act = a as Json;
              return (
                <div
                  key={`${asString(act.id)}-${idx}`}
                  style={{
                    background: '#111',
                    border: '1px solid #333',
                    borderRadius: 6,
                    padding: '0.5rem 0.75rem',
                    fontSize: '0.8rem',
                  }}
                >
                  <div style={{ fontFamily: 'monospace', color: '#888' }}>{asString(act.id).slice(0, 14)}ÔÇª</div>
                  <div>{asString(act.action_type)}</div>
                  <div style={{ color: '#888' }}>{asString(act.command).slice(0, 40)}</div>
                </div>
              );
            })}
          </div>
        </section>
      )}
    </main>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { apiGet, DEFAULT_TENANT_ID } from '../lib/platform-api';

type Json = Record<string, unknown>;

function Box({ title, data }: { title: string; data: unknown }) {
  return (
    <section style={{ background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 16 }}>
      <h3 style={{ marginTop: 0 }}>{title}</h3>
      <pre style={{ margin: 0, color: 'var(--muted)', whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
