const C = {
  bg:     '#0f172a',
  card:   '#1e293b',
  card2:  '#162032',
  border: '#334155',
  text:   '#f1f5f9',
  muted:  '#64748b',
  green:  '#22c55e',
  amber:  '#f59e0b',
