  { name: 'Executor Agent',    model: 'Llama-3 8B',  role: 'Calls tools via FastAPI/MCP, handles retries',color: C.cyan,   icon: 'ÔÜí' },
  { name: 'Critic Agent',      model: 'Llama-3 8B',  role: 'Validates results, checks side effects',      color: C.amber,  icon: '­ƒöì' },
  { name: 'Supervisor Agent',  model: 'DeepSeek R1', role: 'Enforces safety rules, stops risky actions',  color: C.red,    icon: '­ƒøí´©Å' },
];

const SECURITY_RULES = [
