            </div>
          </div>
        </Card>
      )}

      {/* ÔöÇÔöÇ OVERVIEW TAB ÔöÇÔöÇ */}
      {view === 'overview' && (
        <>
          {/* Stats row */}
          {configData && (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(120px, 1fr))', gap: 10, marginBottom: 24 }}>
              <StatBox label="Total Tools"     value={configData.tool_stats.total}                     color={C.blue} />
