                    <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
                      {displayTools.map((t: string) => (
                        <span key={t} style={{ fontSize: 11, background: layer.color + '18', color: layer.color, border: `1px solid ${layer.color}33`, borderRadius: 5, padding: '2px 7px', fontWeight: 600 }}>{t}</span>
