            </div>
          </Card>

          {/* Agent roles */}
          <Card style={{ marginBottom: 24 }}>
            <SectionTitle sub="AutoGen-style multi-agent pattern running in FastAPI">Agent Roles</SectionTitle>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {AGENT_ROLES.map(a => {
