          <Card style={{ marginBottom: 24 }}>
            <SectionTitle sub="At conversation start, backend loads all context and injects into system prompt">Context & Memory</SectionTitle>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 10, marginBottom: 14 }}>
              {[
                { icon: '­ƒæñ', label: 'User Identity',    store: 'PostgreSQL',   color: C.blue,   detail: 'Role, org, permissions, plan' },
                { icon: '­ƒîÉ', label: 'Owned Resources',  store: 'PostgreSQL',   color: C.cyan,   detail: 'Sites, domains, projects' },
                { icon: '­ƒô£', label: 'Recent Activity',  store: 'OpenSearch',   color: C.green,  detail: 'Last actions, errors, tickets' },
                { icon: '­ƒº¼', label: 'Semantic Memory',  store: 'pgvector',     color: C.purple, detail: 'Past conversations, embeddings' },
                { icon: '­ƒôÜ', label: 'Docs & Knowledge', store: 'OpenSearch',   color: C.amber,  detail: 'Help articles, FAQs, SEO docs' },
              ].map(ctx => (
                <div key={ctx.label} style={{ background: C.card2, border: `1px solid ${ctx.color}33`, borderRadius: 10, padding: '14px 16px' }}>
                  <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 8 }}>
                    <span style={{ fontSize: 20 }}>{ctx.icon}</span>
                    <span style={{ fontSize: 12, fontWeight: 700, color: ctx.color }}>{ctx.label}</span>
                  </div>
                  <Badge label={ctx.store} color={ctx.color} />
                  <div style={{ fontSize: 11, color: C.muted, marginTop: 6 }}>{ctx.detail}</div>
                </div>
              ))}
            </div>
          </Card>

          {/* Security rules */}
          <Card style={{ marginBottom: 24 }}>
            <SectionTitle sub="Enforced at every tool call">Security & Safety</SectionTitle>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 14 }}>
              {SECURITY_RULES.map((r, i) => (
                <div key={`item-${i}`} style={{ display: 'flex', gap: 12, padding: '10px 14px', background: C.red + '08', border: `1px solid ${C.red}22`, borderRadius: 10 }}>
                  <span style={{ color: C.red, fontWeight: 900, flexShrink: 0 }}>­ƒöÆ</span>
                  <span style={{ fontSize: 12, color: C.text }}>{r}</span>
                </div>
              ))}
            </div>
            {configData && (
              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                <Badge label={configData.config.allow_high_risk_tools ? 'ÔÜá High-Risk Tools ON' : 'Ô£ô High-Risk Tools OFF'} color={configData.config.allow_high_risk_tools ? C.red : C.green} />
                <Badge label={`Max Auto-Actions: ${configData.config.max_auto_actions}`} color={configData.config.max_auto_actions > 0 ? C.amber : C.green} />
                <Badge label={`Audit: ${configData.health.audit_enabled ? 'Enabled' : 'Disabled'}`} color={configData.health.audit_enabled ? C.green : C.red} />
              </div>
            )}
          </Card>

          {/* MVP Phases */}
          <Card style={{ marginBottom: 24 }}>
            <SectionTitle sub="Phased rollout ÔÇö from internal agent to full Kodee-class">MVP Roadmap</SectionTitle>
            <div style={{ display: 'flex', gap: 10, marginBottom: 16, flexWrap: 'wrap' }}>
              {phases.map((p, i) => {
                const isCurrent = p.status === 'current';
                const phaseColors = [C.green, C.amber, C.blue];
                const color = phaseColors[i];
                return (
                  <button key={p.key} onClick={() => setActivePhase(i)} style={{
                    padding: '8px 16px', borderRadius: 8, fontSize: 12, fontWeight: 700, cursor: 'pointer',
                    border: `1px solid ${activePhase === i ? color : C.border}`,
                    background: activePhase === i ? color + '20' : 'transparent',
                    color: activePhase === i ? color : C.muted,
                  }}>
                    {phaseIcons[i]} {p.label}
                    {isCurrent && <span style={{ marginLeft: 6, fontSize: 9, background: C.green + '30', color: C.green, borderRadius: 4, padding: '1px 5px' }}>LIVE</span>}
                  </button>
                );
              })}
            </div>
            <div style={{ background: C.card2, border: `1px solid ${[C.green, C.amber, C.blue][activePhase]}44`, borderRadius: 12, padding: '18px 22px' }}>
              <div style={{ fontSize: 15, fontWeight: 800, color: [C.green, C.amber, C.blue][activePhase], marginBottom: 12 }}>
                {phaseIcons[activePhase]} {phases[activePhase]?.label}
              </div>
              <div style={{ fontSize: 13, color: C.muted }}>{phases[activePhase]?.description}</div>
            </div>
          </Card>
        </>
      )}

      {/* ÔöÇÔöÇ TOOLS TAB ÔöÇÔöÇ */}
      {view === 'tools' && (
        <div>
          {toolsData && (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(120px, 1fr))', gap: 10, marginBottom: 20 }}>
              <StatBox label="Total Tools"  value={toolsData.total}                                                    color={C.blue} />
              <StatBox label="Low Risk"     value={configData?.tool_stats.by_risk.low ?? 0}    color={C.green} />
              <StatBox label="Medium Risk"  value={configData?.tool_stats.by_risk.medium ?? 0} color={C.amber} />
              <StatBox label="High Risk"    value={configData?.tool_stats.by_risk.high ?? 0}   color={C.red} />
              <StatBox label="Confirm Req." value={configData?.tool_stats.requiring_confirmation ?? 0} color={C.amber} />
              <StatBox label="Groups"       value={toolsData.by_group.length}                  color={C.purple} />
            </div>
          )}

          <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            {(toolsData?.by_group ?? []).map(g => {
              const groupColors: Record<string, string> = {
                'SEO Tools': C.blue, 'Platform Tools': C.green, 'Content Tools': C.purple,
              };
              const color = groupColors[g.group] ?? C.cyan;
              const open = expandedGroup === g.group;
              return (
                <div key={g.group} style={{ background: C.card, border: `1px solid ${color}44`, borderRadius: 12, overflow: 'hidden' }}>
                  <button onClick={() => setExpandedGroup(open ? null : g.group)} style={{
                    width: '100%', background: 'transparent', border: 'none', cursor: 'pointer',
                    padding: '14px 16px', display: 'flex', alignItems: 'center', gap: 10, textAlign: 'left',
                  }}>
                    <span style={{ fontSize: 13, fontWeight: 700, color, flex: 1 }}>{g.group}</span>
                    <span style={{ fontSize: 11, color: C.muted }}>{g.count} tools</span>
                    <span style={{ color: C.muted }}>{open ? 'Ôû▓' : 'Ôû╝'}</span>
                  </button>
                  {open && (
                    <div style={{ borderTop: `1px solid ${C.border}`, padding: '12px 16px', display: 'flex', flexDirection: 'column', gap: 10 }}>
                      {g.tools.map(t => (
                        <div key={t.key} style={{ background: C.card2, border: `1px solid ${C.border}`, borderRadius: 10, padding: '12px 14px' }}>
                          <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12, justifyContent: 'space-between', flexWrap: 'wrap' }}>
                            <div>
                              <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 2 }}>{t.display_name}</div>
                              <code style={{ fontSize: 10, color, fontFamily: 'monospace' }}>{t.fn_signature}</code>
                              {t.description && <div style={{ fontSize: 11, color: C.muted, marginTop: 4 }}>{t.description}</div>}
                              {t.backend_endpoint && (
                                <div style={{ fontSize: 10, color: C.muted, marginTop: 3 }}>
                                  ÔåÆ <code style={{ color: C.cyan }}>{t.backend_endpoint}</code>
                                </div>
                              )}
                            </div>
                            <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }}>
                              <span style={{
                                fontSize: 9, fontWeight: 800, padding: '3px 8px', borderRadius: 5,
                                background: RISK_COLOR[t.risk_level] + '18', color: RISK_COLOR[t.risk_level],
                                border: `1px solid ${RISK_COLOR[t.risk_level]}33`,
                              }}>RISK: {RISK_LABEL[t.risk_level]}</span>
                              {t.requires_confirmation && (
                                <span style={{ fontSize: 9, color: C.amber, border: `1px solid ${C.amber}33`, borderRadius: 5, padding: '3px 8px', background: C.amber + '10' }}>ÔÜá Confirm</span>
                              )}
                              <span style={{ fontSize: 9, color: t.is_active ? C.green : C.red }}>{t.is_active ? 'Ô£ô Active' : 'Ô£ù Off'}</span>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* ÔöÇÔöÇ AUDIT TAB ÔöÇÔöÇ */}
      {view === 'audit' && (
        <div>
          {auditData && (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(130px, 1fr))', gap: 10, marginBottom: 20 }}>
              <StatBox label="Total Calls"  value={auditData.total_calls}   color={C.blue} />
              <StatBox label="Successful"   value={auditData.success_count} color={C.green} />
              <StatBox label="Errors"       value={auditData.error_count}   color={auditData.error_count > 0 ? C.red : C.muted} />
            </div>
          )}

          <Card>
            <SectionTitle sub="Every tool invocation ÔÇö who, what, when">Tool Call Audit Log</SectionTitle>
            {auditData && auditData.calls.length === 0 ? (
              <div style={{ textAlign: 'center', color: C.muted, padding: 40, fontSize: 13 }}>
                No tool calls recorded yet. Start an agent session to generate audit entries.
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                {(auditData?.calls ?? []).map((call, i) => {
                  const statusColor = call.status === 'success' ? C.green : call.status === 'error' ? C.red : call.status === 'pending' ? C.amber : C.muted;
                  return (
                    <div key={`item-${i}`} style={{ display: 'grid', gridTemplateColumns: '160px 100px 80px 80px 1fr', gap: 12, alignItems: 'center', padding: '10px 14px', background: C.card2, border: `1px solid ${C.border}`, borderRadius: 8 }}>
                      <code style={{ fontSize: 11, color: C.cyan }}>{call.tool_key}</code>
                      <span style={{ fontSize: 10, fontWeight: 700, color: statusColor, textTransform: 'uppercase' }}>{call.status}</span>
                      <span style={{ fontSize: 10, color: RISK_COLOR[call.risk_level] ?? C.muted }}>{RISK_LABEL[call.risk_level] ?? '-'} risk</span>
                      <span style={{ fontSize: 10, color: C.muted }}>{call.agent_role ?? '-'}</span>
                      <span style={{ fontSize: 10, color: C.muted }}>{call.created_at ? new Date(call.created_at).toLocaleTimeString() : '-'}</span>
                    </div>
                  );
                })}
              </div>
            )}
          </Card>
        </div>
      )}

      {/* ÔöÇÔöÇ Footer ÔöÇÔöÇ */}
      <div style={{ borderTop: `1px solid ${C.border}`, paddingTop: 16, marginTop: 28, display: 'flex', justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
        <div style={{ fontSize: 10, color: C.muted }}>
          Kodee-Class AI Agent ┬À MCP + AutoGen + LangChain + DeepSeek R1 + FastAPI + Next.js ┬À 100% Open Source
        </div>
        {lastRefresh && <div style={{ fontSize: 10, color: C.muted }}>Refreshed {lastRefresh} ┬À auto 60s</div>}
      </div>
    </div>
  );
}

