'use client';

import { useEffect, useState } from 'react';
import { apiGet, apiSend, DEFAULT_TENANT_ID } from '../lib/platform-api';

type Category = { id: number; name: string; product_count: number };
type Product = {
  id: number;
  name: string;
  sku: string;
  unit_price: number;
  status: string;
  billing_model: string;
  category_id: number | null;
};

type Stats = {
  total_products: number;
  active_products: number;
  total_catalog_value: number;
  by_billing_model: Record<string, number>;
};

export default function ProductsPage() {
  const [tenantId] = useState(DEFAULT_TENANT_ID);
  const [categories, setCategories] = useState<Category[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [stats, setStats] = useState<Stats | null>(null);
  const [catName, setCatName] = useState('Default');
  const [productName, setProductName] = useState('');
  const [price, setPrice] = useState('0');
  const [categoryId, setCategoryId] = useState('');
  const [billingModel, setBillingModel] = useState('one_time');
  const [error, setError] = useState('');

  async function load() {
    try {
      setError('');
      const [catRes, productRes, statsRes] = await Promise.all([
        apiGet<{ categories: Category[] }>('/products/categories', tenantId),
        apiGet<{ products: Product[] }>('/products', tenantId),
        apiGet<Stats & { status: string }>('/products/catalog/stats', tenantId),
      ]);
      setCategories(catRes.categories ?? []);
      setProducts(productRes.products ?? []);
      setStats(statsRes);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load products');
    }
  }

  useEffect(() => {
    void load();
  }, []);

  async function createCategory() {
    try {
      await apiSend('/products/categories', 'POST', { name: catName, description: '' }, tenantId);
      setCatName('');
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Category create failed');
    }
  }

  async function createProduct() {
    try {
      await apiSend(
        '/products',
        'POST',
        {
          name: productName,
          description: '',
          category_id: categoryId ? Number.parseInt(categoryId, 10) : null,
          unit_price: Number.parseFloat(price) || 0,
          billing_model: billingModel,
        },
        tenantId
      );
      setProductName('');
      setPrice('0');
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Product create failed');
    }
  }

  const card = { background: 'var(--bg-soft)', border: '1px solid var(--line)', borderRadius: 12, padding: 16 };
  const input = {
    width: '100%',
    padding: '8px 10px',
    borderRadius: 8,
    border: '1px solid var(--line)',
    background: 'var(--bg)',
    color: 'var(--text)',
    marginBottom: 8,
  };

  return (
    <main style={{ minHeight: '100vh', background: 'var(--bg)', color: 'var(--text)', padding: 24 }}>
      <div style={{ maxWidth: 1100, margin: '0 auto' }}>
        <h1 style={{ marginTop: 0 }}>Products Catalog</h1>
        <p style={{ color: 'var(--muted)' }}>Category hierarchy, product pricing models, and catalog health stats.</p>
        {error && <div style={{ ...card, color: '#f87171', marginBottom: 10 }}>{error}</div>}

        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
            gap: 10,
            marginBottom: 10,
          }}
        >
          <div style={card}>
            <div style={{ color: 'var(--muted)', fontSize: 12 }}>Total Products</div>
            <div style={{ fontSize: 24, fontWeight: 700 }}>{stats?.total_products ?? 0}</div>
          </div>
          <div style={card}>
            <div style={{ color: 'var(--muted)', fontSize: 12 }}>Active Products</div>
            <div style={{ fontSize: 24, fontWeight: 700 }}>{stats?.active_products ?? 0}</div>
          </div>
          <div style={card}>
            <div style={{ color: 'var(--muted)', fontSize: 12 }}>Catalog Value</div>
            <div style={{ fontSize: 24, fontWeight: 700 }}>${stats?.total_catalog_value ?? 0}</div>
          </div>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
          <section style={card}>
            <h3 style={{ marginTop: 0 }}>Create Category</h3>
            <input
              style={input}
              value={catName}
              onChange={(e) => setCatName(e.target.value)}
              placeholder="Category name"
            />
            <button
              onClick={() => void createCategory()}
              style={{
                padding: '8px 12px',
                border: 'none',
                borderRadius: 8,
                background: 'var(--brand)',
                color: '#00101e',
                fontWeight: 700,
              }}
            >
              Create Category
            </button>
