'use client';

import { useEffect, useState } from 'react';
import { adsApi, AdsConnector, AdsPlatform, PLATFORM_LABELS } from '../../lib/ads-api';

const PLATFORMS: AdsPlatform[] = [
  'google_ads',
  'microsoft_ads',
  'amazon_ads',
  'apple_search_ads',
  'youtube_ads',
];

const STATUS_COLORS: Record<string, string> = {
  connected: '#22c55e',
  disconnected: '#6b7280',
  auth_pending: '#f59e0b',
};

const PLATFORM_ACCENT: Record<AdsPlatform, string> = {
  google_ads: '#4285F4',
  microsoft_ads: '#00A4EF',
  amazon_ads: '#f59e0b',
  apple_search_ads: '#cbd5e1',
  youtube_ads: '#ef4444',
};

const PLATFORM_DESC: Record<AdsPlatform, string> = {
  google_ads: 'Search and performance campaigns with broad reach across Google inventory.',
  microsoft_ads: 'Bing and Microsoft Audience ads for incremental CPC-efficient traffic.',
  amazon_ads: 'Retail and marketplace ad placements focused on high-intent shoppers.',
  apple_search_ads: 'App Store search placements optimized for mobile app acquisition.',
  youtube_ads: 'Video-first campaigns with skippable and in-feed ad placements.',
};

function PlatformLogo({ platform }: Readonly<{ platform: AdsPlatform }>) {
  if (platform === 'google_ads') {
    return (
      <div style={{ width: 28, height: 28, borderRadius: 999, background: 'conic-gradient(#4285F4 0 25%, #34A853 25% 50%, #FBBC05 50% 75%, #EA4335 75% 100%)', display: 'grid', placeItems: 'center', flexShrink: 0 }}>
        <div style={{ width: 12, height: 12, borderRadius: 999, background: '#0f172a' }} />
      </div>
    );
  }
  if (platform === 'microsoft_ads') {
    return (
      <div style={{ width: 28, height: 28, borderRadius: 8, background: '#0f172a', border: '1px solid #334155', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 2, padding: 3, boxSizing: 'border-box', flexShrink: 0 }}>
        <div style={{ borderRadius: 2, background: '#F25022' }} />
        <div style={{ borderRadius: 2, background: '#7FBA00' }} />
        <div style={{ borderRadius: 2, background: '#00A4EF' }} />
        <div style={{ borderRadius: 2, background: '#FFB900' }} />
      </div>
    );
  }
  if (platform === 'amazon_ads') {
    return (
      <div style={{ width: 28, height: 28, borderRadius: 999, background: '#111827', border: '1px solid #374151', color: '#f59e0b', display: 'grid', placeItems: 'center', fontSize: 15, fontWeight: 900, flexShrink: 0 }}>
        a
      </div>
    );
  }
  if (platform === 'apple_search_ads') {
    return (
      <div style={{ width: 28, height: 28, borderRadius: 999, background: '#111827', border: '1px solid #4b5563', color: '#e5e7eb', display: 'grid', placeItems: 'center', fontSize: 14, fontWeight: 900, flexShrink: 0 }}>
        A
      </div>
    );
  }
  return (
    <div style={{ width: 28, height: 28, borderRadius: 8, background: '#991b1b', border: '1px solid #ef4444', color: '#ffffff', display: 'grid', placeItems: 'center', fontSize: 12, fontWeight: 900, flexShrink: 0 }}>
      ÔûÂ
    </div>
  );
}

function ConnectorCard({
  connector,
  onConnect,
  onDisconnect,
  busy,
}: Readonly<{
  connector: AdsConnector;
  onConnect: (platform: AdsPlatform) => void;
  onDisconnect: (platform: AdsPlatform) => void;
  busy: boolean;
}>) {
  const color = STATUS_COLORS[connector.status] ?? '#6b7280';
  const accent = PLATFORM_ACCENT[connector.platform] ?? '#3b82f6';

  return (
    <>
      <div
        className="connector-card"
        style={{
          background: 'var(--bg-soft, #111)',
          border: '1px solid var(--line, #333)',
          borderRadius: 14,
          padding: 18,
          boxShadow: '0 2px 8px rgba(2, 6, 23, 0.2)',
          transition: 'transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease, background 0.2s ease',
          ['--accent' as string]: accent,
        }}
      >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
          <div className="connector-logo" style={{ transform: 'scale(1)', transition: 'transform 0.18s ease' }}>
            <PlatformLogo platform={connector.platform} />
          </div>
          <div>
            <div style={{ fontWeight: 800, fontSize: 15 }}>
              {PLATFORM_LABELS[connector.platform] ?? connector.platform}
            </div>
            <div className="connector-description" style={{ fontSize: 12, color: '#64748b', marginTop: 4, lineHeight: 1.45, transition: 'color 0.18s ease' }}>
              {PLATFORM_DESC[connector.platform]}
            </div>
          {connector.connected && (
            <div className="connector-account" style={{ fontSize: 12, color: '#94a3b8', marginTop: 4, transition: 'color 0.18s ease' }}>
              {connector.account_name} ┬À {connector.account_id}
            </div>
          )}
          </div>
        </div>
        <span style={{ borderRadius: 999, padding: '4px 10px', fontSize: 11, fontWeight: 800, background: `${color}22`, color, border: `1px solid ${color}55` }}>
          {connector.status.replace('_', ' ')}
        </span>
      </div>

      {connector.connected && (
        <div style={{ display: 'flex', gap: 12, marginTop: 12 }}>
          <Stat label="Credits Total" value={`$${connector.credit_total.toFixed(0)}`} />
          <Stat label="Credits Left" value={`$${connector.credit_remaining.toFixed(0)}`} />
          <Stat label="Currency" value={connector.credit_currency} />
        </div>
      )}

      <div style={{ display: 'flex', gap: 8, marginTop: 14 }}>
        {connector.connected ? (
          <button
            disabled={busy}
            onClick={() => onDisconnect(connector.platform)}
            style={{ padding: '7px 16px', borderRadius: 8, border: '1px solid #ef4444', color: '#ef4444', background: 'transparent', cursor: busy ? 'not-allowed' : 'pointer', fontSize: 13, fontWeight: 700 }}
          >
            Disconnect
          </button>
        ) : (
          <button
            disabled={busy}
            onClick={() => onConnect(connector.platform)}
            style={{ padding: '7px 16px', borderRadius: 8, border: '1px solid #3b82f6', color: '#93c5fd', background: '#1d4ed822', cursor: busy ? 'not-allowed' : 'pointer', fontSize: 13, fontWeight: 700 }}
          >
            Connect via OAuth
          </button>
        )}
      </div>
      </div>
      <style jsx>{`
        .connector-card:hover,
        .connector-card:focus-within {
          background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 16%, transparent) 0%, rgba(15, 23, 42, 0.92) 75%);
          border-color: var(--accent);
          transform: translateY(-4px);
          box-shadow: 0 12px 26px color-mix(in srgb, var(--accent) 28%, transparent), 0 0 0 1px color-mix(in srgb, var(--accent) 14%, transparent) inset;
        }

        .connector-card:hover .connector-logo,
        .connector-card:focus-within .connector-logo {
          transform: scale(1.08);
        }

        .connector-card:hover .connector-description,
        .connector-card:focus-within .connector-description {
          color: #cbd5e1;
        }

        .connector-card:hover .connector-account,
        .connector-card:focus-within .connector-account {
          color: #e2e8f0;
        }
      `}</style>
    </>
  );
}

function Stat({ label, value }: Readonly<{ label: string; value: string }>) {
  return (
    <div>
      <div style={{ fontSize: 10, color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.06em' }}>{label}</div>
      <div style={{ fontWeight: 800, fontSize: 15, marginTop: 2 }}>{value}</div>
    </div>
  );
}

export default function ConnectorsPage() {
  const [connectors, setConnectors] = useState<AdsConnector[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState<AdsPlatform | null>(null);
  const [error, setError] = useState('');
  const [info, setInfo] = useState('');

  async function refresh() {
    setLoading(true);
    try {
      const res = await adsApi.listConnectors();
      setConnectors(res.connectors);
      setError('');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load connectors.');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => { void refresh(); }, []);

  async function handleConnect(platform: AdsPlatform) {
    setBusy(platform);
    setError('');
    try {
      const { state, authorization_url } = await adsApi.oauthStart(platform);
      // Simulate OAuth callback in dev: code=demo, account derived from platform
      const demoCode = `demo-code-${Date.now()}`;
      const res = await adsApi.oauthCallback(platform, {
        state,
        code: demoCode,
        account_name: `${PLATFORM_LABELS[platform]} ÔÇö Demo Account`,
        account_id: `${platform}-demo-001`,
        scopes: ['ads.read', 'ads.write', 'reports.read'],
        credit_total: 1000,
        credit_remaining: 760,
        credit_currency: 'USD',
      });
      setInfo(`Connected ${PLATFORM_LABELS[platform]}! Auth URL: ${authorization_url.slice(0, 80)}ÔÇª`);
      setConnectors((prev) =>
        prev.map((c) => (c.platform === platform ? res.connector : c))
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'OAuth failed.');
    } finally {
      setBusy(null);
    }
  }

  async function handleDisconnect(platform: AdsPlatform) {
    setBusy(platform);
    setError('');
    try {
      const res = await adsApi.disconnectConnector(platform);
      setConnectors((prev) =>
        prev.map((c) => (c.platform === platform ? res.connector : c))
      );
      setInfo(`${PLATFORM_LABELS[platform]} disconnected.`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Disconnect failed.');
    } finally {
      setBusy(null);
    }
  }

  const connected = connectors.filter((c) => c.connected).length;

  return (
    <main style={{ padding: 24, minHeight: '100vh', background: 'var(--bg, #0a0a0a)', color: 'var(--text, #f1f5f9)' }}>
      <div style={{ maxWidth: 900, margin: '0 auto' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h1 style={{ margin: 0, fontSize: 26 }}>Ad Network Connectors</h1>
            <p style={{ color: '#64748b', marginTop: 6, marginBottom: 0, fontSize: 14 }}>
              Connect ad platforms via OAuth to enable campaign management and reporting.
            </p>
          </div>
          <div style={{ textAlign: 'right' }}>
            <div style={{ fontSize: 28, fontWeight: 900, color: '#22c55e' }}>{connected}</div>
            <div style={{ fontSize: 12, color: '#64748b' }}>of {PLATFORMS.length} connected</div>
          </div>
        </div>

        {error && (
          <div style={{ marginTop: 14, padding: 12, borderRadius: 10, border: '1px solid #ef4444', color: '#fca5a5', background: '#7f1d1d22', fontSize: 13 }}>
            {error}
          </div>
        )}
        {info && (
          <div style={{ marginTop: 14, padding: 12, borderRadius: 10, border: '1px solid #22c55e', color: '#86efac', background: '#14532d22', fontSize: 13 }}>
            {info}
          </div>
        )}

        {loading ? (
          <div style={{ marginTop: 40, textAlign: 'center', color: '#64748b' }}>Loading connectorsÔÇª</div>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 14, marginTop: 20 }}>
            {connectors.map((c) => (
              <ConnectorCard
                key={c.platform}
                connector={c}
                onConnect={handleConnect}
                onDisconnect={handleDisconnect}
                busy={busy === c.platform}
              />
            ))}
          </div>
        )}
      </div>
    </main>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { adsApi, KpiSummary, KpiEngagement } from '../../lib/ads-api';

type ForecastData = {
  horizon_days: number;
  projected_spend: number;
  projected_clicks: number;
  projected_conversions: number;
  projected_roi_pct: number;
};

type CreditData = {
  portfolio_credit_total: number;
  portfolio_credit_remaining: number;
  accounts: { platform: string; account_name: string; credit_remaining: number; currency: string; connected: boolean }[];
};

function KpiCard({
  label,
  value,
  subtext,
  color,
}: Readonly<{ label: string; value: string; subtext?: string; color?: string }>) {
  return (
    <div style={{ background: 'var(--bg-soft, #111)', border: '1px solid var(--line, #333)', borderRadius: 14, padding: '16px 18px' }}>
      <div style={{ fontSize: 11, color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.06em' }}>{label}</div>
      <div style={{ fontSize: 30, fontWeight: 900, marginTop: 8, color: color ?? 'var(--text, #f1f5f9)' }}>{value}</div>
      {subtext && <div style={{ fontSize: 12, color: '#64748b', marginTop: 6 }}>{subtext}</div>}
    </div>
  );
}

function BarChart({
  label,
  items,
  max,
  color,
}: Readonly<{ label: string; items: { label: string; value: number }[]; max: number; color: string }>) {
  return (
    <div>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 10 }}>{label}</div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        {items.map((item) => {
          const pct = max > 0 ? Math.min(100, (item.value / max) * 100) : 0;
          return (
            <div key={item.label}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, color: '#94a3b8', marginBottom: 4 }}>
                <span>{item.label}</span>
                <span style={{ fontWeight: 700 }}>{item.value.toLocaleString()}</span>
              </div>
              <div style={{ height: 8, background: '#1e293b', borderRadius: 999 }}>
                <div style={{ height: 8, background: color, borderRadius: 999, width: `${pct}%`, transition: 'width 0.5s ease' }} />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default function AdsKpiPage() {
  const [kpis, setKpis] = useState<{ summary: KpiSummary; engagement: KpiEngagement } | null>(null);
  const [forecast, setForecast] = useState<ForecastData | null>(null);
  const [credits, setCredits] = useState<CreditData | null>(null);
  const [forecastDays, setForecastDays] = useState(30);
  const [loading, setLoading] = useState(true);
  const [loadingForecast, setLoadingForecast] = useState(false);
  const [error, setError] = useState('');

  async function loadAll(days: number) {
    setLoading(true);
    setError('');
    try {
      const [kpiRes, fcRes, credRes] = await Promise.all([
        adsApi.kpis(),
        adsApi.forecast(days),
        adsApi.credits(),
      ]);
      setKpis({ summary: kpiRes.summary, engagement: kpiRes.engagement });
      setForecast(fcRes);
      setCredits(credRes);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load KPIs.');
    } finally {
      setLoading(false);
    }
  }

  async function refreshForecast(days: number) {
    setLoadingForecast(true);
    try {
      const res = await adsApi.forecast(days);
      setForecast(res);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Forecast failed.');
    } finally {
      setLoadingForecast(false);
    }
  }

  useEffect(() => { void loadAll(forecastDays); }, []); // eslint-disable-line react-hooks/exhaustive-deps

  function handleForecastDays(days: number) {
    setForecastDays(days);
    void refreshForecast(days);
  }

  const s = kpis?.summary;
  const eng = kpis?.engagement;

  return (
    <main style={{ padding: 24, minHeight: '100vh', background: 'var(--bg, #0a0a0a)', color: 'var(--text, #f1f5f9)' }}>
      <div style={{ maxWidth: 1180, margin: '0 auto' }}>
        <h1 style={{ margin: 0, fontSize: 26 }}>Ads KPI & Analytics</h1>
        <p style={{ color: '#64748b', marginTop: 6, marginBottom: 0, fontSize: 14 }}>
          Cross-network performance overview, forecasting, and credit balances.
        </p>

        {error && <div style={{ marginTop: 12, padding: 12, borderRadius: 10, border: '1px solid #ef4444', color: '#fca5a5', background: '#7f1d1d22', fontSize: 13 }}>{error}</div>}

        {loading ? (
          <div style={{ marginTop: 40, textAlign: 'center', color: '#64748b' }}>Loading KPIsÔÇª</div>
        ) : (
          <>
            {/* Primary KPI grid */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: 12, marginTop: 20 }}>
              <KpiCard label="Campaigns" value={String(s?.campaigns_total ?? 0)} subtext={`${s?.campaigns_active ?? 0} active`} />
              <KpiCard label="ROI" value={`${(s?.roi_pct ?? 0).toFixed(1)}%`} color={(s?.roi_pct ?? 0) >= 0 ? '#22c55e' : '#ef4444'} subtext="Revenue vs spend" />
              <KpiCard label="Success Ratio" value={`${(s?.success_ratio_pct ?? 0).toFixed(1)}%`} subtext="Conversions / clicks" />
              <KpiCard label="Spend" value={`$${(s?.spend ?? 0).toLocaleString()}`} />
              <KpiCard label="Revenue" value={`$${(s?.revenue ?? 0).toLocaleString()}`} color="#22c55e" />
              <KpiCard label="CPA" value={`$${(s?.cpa ?? 0).toFixed(2)}`} subtext="Cost per acquisition" />
              <KpiCard label="CPC" value={`$${(s?.cpc ?? 0).toFixed(2)}`} subtext="Cost per click" />
              <KpiCard label="CTR" value={`${(s?.ctr_pct ?? 0).toFixed(2)}%`} subtext="Click-through rate" />
            </div>

            {/* Engagement + forecast + credits */}
            <div style={{ display: 'grid', gridTemplateColumns: '1.4fr 1fr', gap: 16, marginTop: 18 }}>
              {/* Left: engagement bars + forecast */}
              <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                <div style={{ background: 'var(--bg-soft, #111)', border: '1px solid var(--line, #333)', borderRadius: 14, padding: 18 }}>
                  <BarChart
                    label="Engagement Breakdown"
                    items={[
                      { label: 'Impressions', value: eng?.impressions ?? 0 },
                      { label: 'Clicks', value: eng?.clicks ?? 0 },
                      { label: 'Conversions', value: eng?.conversions ?? 0 },
                      { label: 'Likes', value: eng?.likes ?? 0 },
                      { label: 'Shares', value: eng?.shares ?? 0 },
                      { label: 'Comments', value: eng?.comments ?? 0 },
                    ]}
                    max={Math.max(eng?.impressions ?? 1, 1)}
                    color="#3b82f6"
                  />
                </div>

                {/* Forecast */}
                <div style={{ background: 'var(--bg-soft, #111)', border: '1px solid var(--line, #333)', borderRadius: 14, padding: 18 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span style={{ fontWeight: 700, fontSize: 14 }}>Forecast</span>
                    <div style={{ display: 'flex', gap: 6 }}>
                      {[7, 14, 30, 90].map((d) => (
                        <button
                          key={d}
                          disabled={loadingForecast}
                          onClick={() => handleForecastDays(d)}
                          style={{
                            padding: '4px 10px', borderRadius: 8, fontSize: 12, fontWeight: 700,
                            border: forecastDays === d ? '1px solid #3b82f6' : '1px solid var(--line, #333)',
                            color: forecastDays === d ? '#93c5fd' : '#64748b',
                            background: forecastDays === d ? '#1d4ed822' : 'transparent',
                            cursor: loadingForecast ? 'not-allowed' : 'pointer',
                          }}
                        >
                          {d}d
                        </button>
                      ))}
                    </div>
                  </div>

                  {forecast && (
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginTop: 14 }}>
                      <div style={{ textAlign: 'center' }}>
                        <div style={{ fontSize: 10, color: '#64748b', textTransform: 'uppercase' }}>Projected Spend</div>
                        <div style={{ fontWeight: 900, fontSize: 22, marginTop: 4 }}>${forecast.projected_spend.toLocaleString()}</div>
                      </div>
                      <div style={{ textAlign: 'center' }}>
                        <div style={{ fontSize: 10, color: '#64748b', textTransform: 'uppercase' }}>Projected ROI</div>
                        <div style={{ fontWeight: 900, fontSize: 22, marginTop: 4, color: forecast.projected_roi_pct >= 0 ? '#22c55e' : '#ef4444' }}>
                          {forecast.projected_roi_pct.toFixed(1)}%
                        </div>
                      </div>
                      <div style={{ textAlign: 'center' }}>
                        <div style={{ fontSize: 10, color: '#64748b', textTransform: 'uppercase' }}>Projected Clicks</div>
                        <div style={{ fontWeight: 900, fontSize: 22, marginTop: 4 }}>{forecast.projected_clicks.toLocaleString()}</div>
                      </div>
                      <div style={{ textAlign: 'center' }}>
                        <div style={{ fontSize: 10, color: '#64748b', textTransform: 'uppercase' }}>Projected Conversions</div>
                        <div style={{ fontWeight: 900, fontSize: 22, marginTop: 4 }}>{forecast.projected_conversions.toLocaleString()}</div>
                      </div>
                    </div>
                  )}
                </div>
              </div>

              {/* Right: credits + pacing */}
              <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                <div style={{ background: 'var(--bg-soft, #111)', border: '1px solid var(--line, #333)', borderRadius: 14, padding: 18 }}>
                  <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 12 }}>Credit Balances</div>
                  {credits && (
                    <>
                      <div style={{ display: 'flex', gap: 20, marginBottom: 14 }}>
                        <div>
                          <div style={{ fontSize: 10, color: '#64748b', textTransform: 'uppercase' }}>Portfolio Total</div>
                          <div style={{ fontWeight: 900, fontSize: 22 }}>${credits.portfolio_credit_total.toLocaleString()}</div>
                        </div>
                        <div>
                          <div style={{ fontSize: 10, color: '#64748b', textTransform: 'uppercase' }}>Remaining</div>
                          <div style={{ fontWeight: 900, fontSize: 22, color: '#22c55e' }}>${credits.portfolio_credit_remaining.toLocaleString()}</div>
                        </div>
                      </div>
                      <BarChart
                        label=""
                        items={credits.accounts
                          .filter((a) => a.connected)
                          .map((a) => ({ label: a.account_name || a.platform, value: a.credit_remaining }))}
                        max={credits.portfolio_credit_total || 1}
                        color="#22c55e"
                      />
                    </>
                  )}
                </div>

                {/* Budget pacing */}
                <div style={{ background: 'var(--bg-soft, #111)', border: '1px solid var(--line, #333)', borderRadius: 14, padding: 18 }}>
                  <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 12 }}>Budget Pacing</div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                    <div>
                      <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, color: '#94a3b8', marginBottom: 4 }}>
                        <span>Spend vs Daily Budget</span>
                        <span style={{ fontWeight: 700 }}>
                          ${(s?.spend ?? 0).toFixed(0)} / ${(s?.budget_daily ?? 0).toFixed(0)}
                        </span>
                      </div>
                      <div style={{ height: 10, background: '#1e293b', borderRadius: 999 }}>
                        <div style={{
                          height: 10, background: '#f59e0b', borderRadius: 999,
                          width: `${s?.budget_daily ? Math.min(100, (s.spend / s.budget_daily) * 100) : 0}%`,
                          transition: 'width 0.5s',
                        }} />
                      </div>
                    </div>
                    <div>
                      <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, color: '#94a3b8', marginBottom: 4 }}>
                        <span>Spend vs Total Budget</span>
                        <span style={{ fontWeight: 700 }}>
                          ${(s?.spend ?? 0).toFixed(0)} / ${(s?.budget_total ?? 0).toFixed(0)}
                        </span>
                      </div>
                      <div style={{ height: 10, background: '#1e293b', borderRadius: 999 }}>
                        <div style={{
                          height: 10, background: '#3b82f6', borderRadius: 999,
                          width: `${s?.budget_total ? Math.min(100, (s.spend / s.budget_total) * 100) : 0}%`,
                          transition: 'width 0.5s',
                        }} />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </>
        )}
      </div>
    </main>
  );
}

