      )}

      {/* Groups View */}
      {view === 'groups' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 32, marginBottom: 28 }}>
          {groups
            .filter(g => !filterGroup || g.group === filterGroup)
            .map(g => {
              const color = GROUP_COLORS[g.group] ?? C.blue;
              const items = g.items.filter(m => {
                const q = searchQ.toLowerCase();
                return !q || m.display_name.toLowerCase().includes(q) || m.key.toLowerCase().includes(q);
              });
              if (!items.length) return null;
              const avg = Math.round(items.reduce((s, m) => s + moduleScore(m), 0) / items.length);
              return (
                <div key={g.group}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 12 }}>
                    <div style={{ width: 4, height: 32, background: color, borderRadius: 4 }} />
                    <div>
                      <div style={{ fontSize: 13, fontWeight: 700, color }}>{g.group}</div>
                      <div style={{ fontSize: 11, color: C.muted }}>{items.length} modules ┬À avg {avg}/100</div>
                    </div>
                    <div style={{ marginLeft: 'auto', background: color + '20', border: `1px solid ${color}44`, borderRadius: 20, padding: '3px 12px', fontSize: 12, fontWeight: 700, color }}>
                      {avg}/100
                    </div>
                  </div>
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: 12 }}>
                    {items.map(m => <ModuleCard key={m.key} m={m} globalIdx={g.items.indexOf(m)} />)}
                  </div>
                </div>
              );
            })}
        </div>
      )}

      {/* Group scorecard table */}
      <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 14, padding: '20px 24px', marginBottom: 24 }}>
        <div style={{ fontSize: 12, fontWeight: 700, color: C.muted, textTransform: 'uppercase', letterSpacing: 1, marginBottom: 16 }}>Group Scorecard</div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          {groups.map(g => {
            const color = GROUP_COLORS[g.group] ?? C.blue;
            const avg = Math.round(g.items.reduce((s, m) => s + moduleScore(m), 0) / g.items.length);
            const implCount = g.items.filter(m => m.implemented).length;
            return (
              <div key={g.group} style={{ display: 'grid', gridTemplateColumns: '180px 50px 1fr 100px', gap: 12, alignItems: 'center' }}>
                <div style={{ fontSize: 12, color: C.text, display: 'flex', alignItems: 'center', gap: 8 }}>
                  <div style={{ width: 8, height: 8, borderRadius: '50%', background: color, flexShrink: 0 }} />
                  <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{g.group}</span>
                </div>
                <div style={{ fontSize: 12, color: C.muted, textAlign: 'right' }}>{g.items.length}m</div>
                <div style={{ background: C.border, borderRadius: 6, height: 8, overflow: 'hidden' }}>
                  <div style={{ width: `${avg}%`, height: '100%', background: color, borderRadius: 6, transition: 'width 1s ease' }} />
                </div>
                <div style={{ fontSize: 12, fontWeight: 700, color, textAlign: 'right' }}>{avg}/100 ({implCount}/{g.items.length})</div>
              </div>
            );
          })}
          <div style={{ borderTop: `1px solid ${C.border}`, paddingTop: 10, display: 'grid', gridTemplateColumns: '180px 50px 1fr 100px', gap: 12, alignItems: 'center', marginTop: 4 }}>
            <div style={{ fontSize: 13, fontWeight: 800, color: gradeColor(platformGrade) }}>TOTAL</div>
            <div style={{ fontSize: 12, color: C.muted, textAlign: 'right' }}>{totalModules}m</div>
            <div style={{ background: C.border, borderRadius: 6, height: 10, overflow: 'hidden' }}>
              <div style={{ width: `${platformScore}%`, height: '100%', background: gradeColor(platformGrade), borderRadius: 6, transition: 'width 1s ease' }} />
            </div>
            <div style={{ fontSize: 14, fontWeight: 900, color: gradeColor(platformGrade), textAlign: 'right' }}>{platformScore}/100</div>
          </div>
        </div>
      </div>

      {/* Ranked actions */}
      {intel && intel.ranked_actions.length > 0 && (
        <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 14, padding: '20px 24px', marginBottom: 24 }}>
          <div style={{ fontSize: 12, fontWeight: 700, color: C.muted, textTransform: 'uppercase', letterSpacing: 1, marginBottom: 16 }}>Ranked Action Items</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {intel.ranked_actions.map((a, i) => (
              <div key={`item-${i}`} style={{
                display: 'flex', gap: 12, padding: '10px 14px',
                background: priorityColor(a.priority) + '10',
                border: `1px solid ${priorityColor(a.priority)}33`,
                borderRadius: 10,
              }}>
                <div style={{ minWidth: 54, fontSize: 9, fontWeight: 800, color: priorityColor(a.priority), textTransform: 'uppercase', paddingTop: 1 }}>{a.priority}</div>
                <div style={{ fontSize: 12, color: C.text }}>{a.action}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Footer */}
      <div style={{ borderTop: `1px solid ${C.border}`, paddingTop: 16, display: 'flex', justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
        <div style={{ fontSize: 10, color: C.muted }}>
          SEO Platform Matrix ┬À {totalModules} modules ┬À Grade {platformGrade} ┬À {platformScore}/100 ┬À DeepSeek R1 + FastAPI + Next.js + PostgreSQL + OpenSearch
        </div>
        {lastRefresh && <div style={{ fontSize: 10, color: C.muted }}>Refreshed {lastRefresh} ┬À auto 60s</div>}
      </div>
    </div>
  );
}

