'use client';

import { useCallback, useEffect, useRef, useState } from 'react';

// ÔöÇÔöÇ Types ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

type Sentiment = 'positive' | 'neutral' | 'negative';
type Platform = 'linkedin' | 'x' | 'instagram' | 'facebook' | 'reddit' | 'youtube' | 'news';
type CrisisLevel = 'none' | 'watch' | 'high' | 'critical';

interface Mention {
  id: number;
  platform: string;
  query: string;
  author_handle: string;
  text: string;
  sentiment: Sentiment;
  engagement_count: number;
  created_at: string;
}

interface AlertRule {
  id: number;
  name: string;
  query: string | null;
  platform: string | null;
  min_engagement: number;
  negative_only: boolean;
  enabled: boolean;
  created_at: string;
}

interface Alert {
  id: number;
  rule_name: string;
  mention_id: number;
  severity: 'medium' | 'high';
  status: 'open' | 'closed';
  created_at: string;
}

interface Cluster {
  query: string;
  platform: string;
  sentiment: Sentiment;
  mentions: number;
}

interface Summary {
  total_mentions: number;
  sentiment: { positive: number; neutral: number; negative: number };
  platforms: Record<string, number>;
  top_queries: { query: string; mentions: number }[];
  avg_engagement: number;
  clusters: { cluster: string; query: string; platform: string; mentions: number }[];
  alerts_open: number;
  crisis: {
    triggered: boolean;
    level: CrisisLevel;
    negative_ratio: number;
    high_negative_mentions: number;
  };
}

// ÔöÇÔöÇ Constants ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

const API_BASE = '/api/fastapi';
const DEFAULT_TENANT = process.env.NEXT_PUBLIC_DEFAULT_TENANT_ID ?? 'tenant-demo';

const SENTIMENT_COLORS: Record<Sentiment, string> = {
  positive: '#26d78e',
  neutral: '#1bc7ff',
  negative: '#f87171',
};

const CRISIS_COLORS: Record<CrisisLevel, string> = {
  none: '#26d78e',
  watch: '#f59e0b',
  high: '#f97316',
  critical: '#ef4444',
};

const PLATFORM_ICONS: Record<string, string> = {
  linkedin: '­ƒÆ╝',
  x: '­ØòÅ',
  instagram: '­ƒô©',
  facebook: '­ƒæÑ',
  reddit: '­ƒƒá',
  youtube: 'ÔûÂ´©Å',
  news: '­ƒô░',
};

// ÔöÇÔöÇ Helpers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

async function apiFetch(path: string, tenantId: string, opts?: RequestInit) {
  const res = await fetch(`${API_BASE}${path}`, {
    ...opts,
    headers: {
      'Content-Type': 'application/json',
      'X-Tenant-Id': tenantId,
      ...(opts?.headers ?? {}),
    },
  });
  const data = await res.json();
  if (!res.ok) throw new Error((data?.detail as string) ?? `HTTP ${res.status}`);
  return data;
}

function timeAgo(iso: string) {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60_000);
  if (m < 1) return 'just now';
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

// ÔöÇÔöÇ Sub-components ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

function Card({ children, style }: Readonly<{ children: React.ReactNode; style?: React.CSSProperties }>) {
  return (
    <div
      style={{
        background: 'var(--bg-soft)',
        border: '1px solid var(--line)',
        borderRadius: 12,
        padding: '20px 24px',
        ...style,
      }}
    >
      {children}
    </div>
  );
}

function SectionTitle({ children }: Readonly<{ children: React.ReactNode }>) {
  return (
    <h2
      style={{
        margin: '0 0 16px',
        fontSize: 15,
        fontWeight: 600,
        color: 'var(--brand)',
        textTransform: 'uppercase',
        letterSpacing: '0.07em',
      }}
    >
      {children}
    </h2>
  );
}

function Pill({ label, color, small }: Readonly<{ label: string; color: string; small?: boolean }>) {
  return (
    <span
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        padding: small ? '2px 8px' : '4px 10px',
        borderRadius: 99,
        fontSize: small ? 11 : 12,
        fontWeight: 600,
        background: `${color}22`,
        color,
        border: `1px solid ${color}55`,
      }}
    >
      {label}
    </span>
  );
}

function StatCard({
  label,
  value,
  sub,
  accent,
}: Readonly<{ label: string; value: string | number; sub?: string; accent?: string }>) {
  return (
    <Card>
      <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 6 }}>{label}</div>
      <div
        style={{
          fontSize: 28,
          fontWeight: 700,
          color: accent ?? 'var(--text)',
          lineHeight: 1,
        }}
      >
        {value}
      </div>
      {sub && <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 4 }}>{sub}</div>}
    </Card>
  );
}

function SentimentDonut({ sentiment }: Readonly<{ sentiment: Summary['sentiment'] }>) {
  const total = sentiment.positive + sentiment.neutral + sentiment.negative;
  if (total === 0)
    return (
      <svg viewBox="0 0 120 120" width={120} height={120}>
        <circle cx={60} cy={60} r={50} fill="none" stroke="var(--line)" strokeWidth={20} />
        <text x={60} y={66} textAnchor="middle" fontSize={14} fill="var(--muted)">
          No data
        </text>
      </svg>
    );

  const R = 50;
  const cx = 60;
  const cy = 60;
  const gap = 4;
  const segments: { key: Sentiment; count: number }[] = [
    { key: 'positive', count: sentiment.positive },
    { key: 'neutral', count: sentiment.neutral },
    { key: 'negative', count: sentiment.negative },
  ];

  let startAngle = -Math.PI / 2;
  const paths: React.ReactNode[] = [];

  for (const seg of segments) {
    if (seg.count === 0) continue;
    const frac = seg.count / total;
    const sweep = frac * 2 * Math.PI - (gap * Math.PI) / 180;
    const endAngle = startAngle + sweep;
    const x1 = cx + R * Math.cos(startAngle);
    const y1 = cy + R * Math.sin(startAngle);
    const x2 = cx + R * Math.cos(endAngle);
    const y2 = cy + R * Math.sin(endAngle);
    const largeArc = sweep > Math.PI ? 1 : 0;
    paths.push(
      <path
        key={seg.key}
        d={`M ${x1} ${y1} A ${R} ${R} 0 ${largeArc} 1 ${x2} ${y2}`}
        fill="none"
        stroke={SENTIMENT_COLORS[seg.key]}
        strokeWidth={20}
        strokeLinecap="round"
      />
    );
    startAngle = endAngle + (gap * Math.PI) / 180;
  }

  const negPct = total > 0 ? Math.round((sentiment.negative / total) * 100) : 0;

  return (
    <svg viewBox="0 0 120 120" width={120} height={120}>
      {paths}
      <text x={60} y={57} textAnchor="middle" fontSize={18} fontWeight="700" fill="var(--text)">
        {negPct}%
      </text>
      <text x={60} y={72} textAnchor="middle" fontSize={10} fill="var(--muted)">
        negative
      </text>
    </svg>
  );
}

function CrisisBadge({ level }: Readonly<{ level: CrisisLevel }>) {
  const labels: Record<CrisisLevel, string> = {
    none: 'Ô£à No Crisis',
    watch: 'ÔÜá´©Å Watch',
    high: '­ƒöÑ High Risk',
    critical: '­ƒÜ¿ CRITICAL',
  };
  return (
    <div
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: 6,
        padding: '6px 14px',
        borderRadius: 99,
        fontWeight: 700,
        fontSize: 13,
        color: CRISIS_COLORS[level],
        background: `${CRISIS_COLORS[level]}18`,
        border: `1.5px solid ${CRISIS_COLORS[level]}55`,
      }}
    >
      {labels[level]}
    </div>
  );
}

function BarRow({
  label,
  value,
  max,
  color,
  extra,
}: Readonly<{ label: string; value: number; max: number; color: string; extra?: string }>) {
  const pct = max > 0 ? Math.round((value / max) * 100) : 0;
  return (
    <div style={{ marginBottom: 10 }}>
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          fontSize: 12,
          color: 'var(--muted)',
          marginBottom: 4,
        }}
      >
        <span>{label}</span>
        <span>
          {value} {extra}
        </span>
      </div>
      <div
        style={{
          height: 6,
          borderRadius: 3,
          background: 'var(--line)',
          overflow: 'hidden',
        }}
      >
        <div
          style={{
            height: '100%',
            width: `${pct}%`,
            background: color,
            borderRadius: 3,
            transition: 'width 0.4s',
          }}
        />
      </div>
    </div>
  );
}

// ÔöÇÔöÇ Main Page ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

export default function SocialListeningPage() {
  const [tenantId] = useState(DEFAULT_TENANT);

  // Data state
  const [summary, setSummary] = useState<Summary | null>(null);
  const [mentions, setMentions] = useState<Mention[]>([]);
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [clusters, setClusters] = useState<Cluster[]>([]);
  const [rules, setRules] = useState<AlertRule[]>([]);

  // UI state
  const [tab, setTab] = useState<'overview' | 'mentions' | 'alerts' | 'rules' | 'ingest'>('overview');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  // Ingest form
  const [ingestPlatform, setIngestPlatform] = useState<Platform>('linkedin');
  const [ingestQuery, setIngestQuery] = useState('brand reputation');
  const [ingestHandle, setIngestHandle] = useState('@user');
  const [ingestText, setIngestText] = useState('');
  const [ingestSentiment, setIngestSentiment] = useState<Sentiment>('neutral');
  const [ingestEngagement, setIngestEngagement] = useState('0');

  // Alert rule form
  const [ruleName, setRuleName] = useState('');
  const [ruleQuery, setRuleQuery] = useState('');
  const [rulePlatform, setRulePlatform] = useState('');
  const [ruleMinEngagement, setRuleMinEngagement] = useState('20');
  const [ruleNegOnly, setRuleNegOnly] = useState(true);

  const refreshTimer = useRef<ReturnType<typeof setInterval> | null>(null);

  const loadAll = useCallback(async () => {
    try {
      const [sumRes, mentRes, alertRes, clusterRes] = await Promise.all([
        apiFetch('/social/listening/summary', tenantId),
        apiFetch('/social/listening/mentions', tenantId),
        apiFetch('/social/listening/alerts', tenantId),
        apiFetch('/social/listening/clusters', tenantId),
      ]);
      setSummary(sumRes.summary as Summary);
      setMentions((mentRes.mentions as Mention[]) ?? []);
      setAlerts((alertRes.alerts as Alert[]) ?? []);
      setClusters((clusterRes.clusters as Cluster[]) ?? []);
    } catch {
      // silently ignore background refresh errors
    }
  }, [tenantId]);

  useEffect(() => {
    loadAll();
    refreshTimer.current = setInterval(loadAll, 30_000);
    return () => {
      if (refreshTimer.current) clearInterval(refreshTimer.current);
    };
  }, [loadAll]);

  const notify = (msg: string, isError = false) => {
    if (isError) {
      setError(msg);
      setSuccess('');
    } else {
      setSuccess(msg);
      setError('');
    }
    setTimeout(() => {
      setError('');
      setSuccess('');
    }, 4000);
  };

  async function handleIngest() {
    if (!ingestText.trim()) {
      notify('Mention text is required.', true);
      return;
    }
    setLoading(true);
    try {
      await apiFetch('/social/listening/ingest', tenantId, {
        method: 'POST',
        body: JSON.stringify({
          platform: ingestPlatform,
          query: ingestQuery,
          author_handle: ingestHandle,
          text: ingestText,
          sentiment: ingestSentiment,
          engagement_count: Math.max(0, Number.parseInt(ingestEngagement, 10) || 0),
        }),
      });
      setIngestText('');
      notify('Mention ingested successfully.');
      await loadAll();
    } catch (e: unknown) {
      notify((e as Error).message, true);
    } finally {
      setLoading(false);
    }
  }

  async function handleCreateRule() {
    if (!ruleName.trim()) {
      notify('Rule name is required.', true);
      return;
    }
    setLoading(true);
    try {
      const res = await apiFetch('/social/listening/rules', tenantId, {
        method: 'POST',
        body: JSON.stringify({
          name: ruleName,
          query: ruleQuery || null,
          platform: rulePlatform || null,
          min_engagement: Math.max(0, Number.parseInt(ruleMinEngagement, 10) || 0),
          negative_only: ruleNegOnly,
        }),
      });
      setRules((prev) => [res.rule as AlertRule, ...prev]);
      setRuleName('');
      setRuleQuery('');
      setRulePlatform('');
      notify('Alert rule created.');
    } catch (e: unknown) {
      notify((e as Error).message, true);
    } finally {
      setLoading(false);
    }
  }

  // ÔöÇÔöÇ Styles ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const page: React.CSSProperties = {
    minHeight: '100vh',
    background: 'var(--bg)',
    color: 'var(--text)',
    padding: '32px 24px',
    fontFamily: 'var(--font-geist-sans, system-ui, sans-serif)',
  };

  const container: React.CSSProperties = {
    maxWidth: 1080,
    margin: '0 auto',
  };

  const tabBar: React.CSSProperties = {
    display: 'flex',
    gap: 4,
    marginBottom: 28,
    borderBottom: '1px solid var(--line)',
    paddingBottom: 0,
  };

  const tabBtn = (active: boolean): React.CSSProperties => ({
    padding: '8px 18px',
    borderRadius: '8px 8px 0 0',
    border: 'none',
    background: active ? 'var(--brand)' : 'transparent',
    color: active ? '#000' : 'var(--muted)',
    fontWeight: active ? 700 : 500,
    fontSize: 13,
    cursor: 'pointer',
    transition: 'all 0.15s',
  });

  const input: React.CSSProperties = {
    width: '100%',
    padding: '8px 12px',
    borderRadius: 8,
    border: '1px solid var(--line)',
    background: 'var(--bg)',
    color: 'var(--text)',
    fontSize: 13,
    marginBottom: 10,
    boxSizing: 'border-box',
  };

  const select: React.CSSProperties = { ...input };

  const btn: React.CSSProperties = {
    padding: '9px 20px',
    borderRadius: 8,
    border: 'none',
    background: 'var(--brand)',
    color: '#000',
    fontWeight: 700,
    fontSize: 13,
    cursor: loading ? 'not-allowed' : 'pointer',
    opacity: loading ? 0.6 : 1,
  };

  const grid2: React.CSSProperties = {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
    gap: 16,
    marginBottom: 20,
  };

  const grid4: React.CSSProperties = {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(170px, 1fr))',
    gap: 16,
    marginBottom: 20,
  };

  // ÔöÇÔöÇ Tab content ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const openAlerts = alerts.filter((a) => a.status === 'open');
  const criticalAlerts = openAlerts.filter((a) => a.severity === 'high');

  const platformMax = summary ? Math.max(...Object.values(summary.platforms), 1) : 1;

  return (
    <div style={page}>
      <div style={container}>
        {/* Header */}
        <div style={{ marginBottom: 28 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 6 }}>
            <div
              style={{
                width: 40,
                height: 40,
                borderRadius: 10,
                background: 'linear-gradient(135deg, #1bc7ff, #26d78e)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: 20,
              }}
            >
              ­ƒôí
            </div>
            <div>
              <h1
                style={{
                  margin: 0,
                  fontSize: 24,
                  fontWeight: 800,
                  background: 'linear-gradient(90deg, var(--brand), var(--brand-2))',
                  WebkitBackgroundClip: 'text',
                  WebkitTextFillColor: 'transparent',
                }}
              >
                Social Listening
              </h1>
              <p style={{ margin: 0, fontSize: 13, color: 'var(--muted)' }}>
                Real-time brand monitoring ┬À Sentiment analysis ┬À Crisis detection ┬À Alert rules
              </p>
            </div>
            {summary && (
              <div style={{ marginLeft: 'auto' }}>
                <CrisisBadge level={summary.crisis.level} />
              </div>
            )}
          </div>
        </div>

        {/* Toast */}
        {(error || success) && (
          <div
            style={{
              padding: '10px 16px',
              borderRadius: 8,
              marginBottom: 16,
              background: error ? '#ef444422' : '#26d78e22',
              border: `1px solid ${error ? '#ef4444' : '#26d78e'}55`,
