function CaptionsPanel({ captionPackId, setCaptionPackId, selectedCaptionPack, ugcStyleCategoryId, setUgcStyleCategoryId: _setUgcStyleCategoryId, ugcPreviewTemplateId, setUgcPreviewTemplateId: _setUgcPreviewTemplateId, visibleUgcPreviewTemplates, captionPlatform, setCaptionPlatform, captionObjective, setCaptionObjective, captionTone, setCaptionTone, captionLength, setCaptionLength, captionVariantCount, setCaptionVariantCount, captionHookStyle, setCaptionHookStyle, captionCtaStrength, setCaptionCtaStrength, captionEmojiDensity, setCaptionEmojiDensity, captionAutoHashtags, setCaptionAutoHashtags, isGeneratingCaptions, setIsGeneratingCaptions, captions, setCaptions, selectedCaptionId, setSelectedCaptionId, subtitles: _subtitles, ugcTemplateSyncError, videoCanvasAspectRatio, setVideoCanvasAspectRatio, videoBackgroundMedia, setVideoBackgroundMedia, videoScriptStyle, setVideoScriptStyle, videoSubtitlesAuto, setVideoSubtitlesAuto, videoSubtitlesLanguage, setVideoSubtitlesLanguage, videoAutoAdjustPlatforms, setVideoAutoAdjustPlatforms, selectUgcStyleCategory, applyUgcPreviewTemplate, applyUgcPlatformPreset, generateCaptionVariants, captionsVideoConfigNote }: Readonly<CaptionsPanelProps>) {
