  function buildPublishTarget(): PublishTarget {
    const textBundle = slides
      .map((slide, index) => `${index + 1}. ${slide.headline} - ${slide.subheadline}`)
      .join('\n');
    const mediaUrls = slides.map((slide) => slide.imageUrl).filter(Boolean);
