          color: #f5d0fe;
        }

        .text-style-serif .text-style-line-primary {
          font-family: 'Georgia', serif;
          font-size: 20px;
          font-weight: 700;
        }

        .editor-insert-groups,
        .editor-stack-list {
          display: grid;
          gap: 10px;
        }

        .insert-item-btn,
        .editor-stack-item {
          border-radius: 14px;
          padding: 12px 14px;
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: 10px;
          cursor: pointer;
        }

        .editor-stack-main {
          border: 0;
          background: transparent;
          color: inherit;
          font: inherit;
          text-align: left;
          cursor: pointer;
          flex: 1 1 auto;
          padding: 0;
        }

        .layer-visibility-pill {
          border: 1px solid var(--line);
          border-radius: 999px;
          padding: 6px 10px;
          font-size: 11px;
          font-weight: 700;
          cursor: pointer;
          background: rgba(255, 255, 255, 0.04);
          color: var(--muted);
          flex: 0 0 auto;
        }

        .layer-visibility-pill.visible {
          color: var(--fg);
          border-color: color-mix(in oklab, var(--brand) 44%, var(--line));
          background: color-mix(in oklab, var(--brand) 16%, rgba(255, 255, 255, 0.04));
        }

        .layer-visibility-pill.hidden {
          opacity: 0.82;
        }

        .insert-item-icon {
          width: 28px;
          height: 28px;
          border-radius: 9px;
          display: grid;
          place-items: center;
          background: rgba(255, 255, 255, 0.05);
          color: var(--fg);
          flex: 0 0 auto;
        }

        .canvas-zone-modern {
          padding: 18px;
          min-height: 720px;
          display: grid;
          gap: 16px;
        }

        .editor-zoom-cluster input {
          width: 180px;
        }

        .canvas-stage {
          min-height: 620px;
          border-radius: 20px;
          background: radial-gradient(circle at top, rgba(255, 255, 255, 0.08), transparent 48%), #111827;
          display: grid;
          place-items: center;
          padding: 18px;
        }

        .creative-artboard {
          width: 100%;
          min-height: 100%;
          border-radius: 26px;
          background: linear-gradient(180deg, #0f172a, #111827 48%, #020617);
          color: white;
          padding: 26px;
          position: relative;
          overflow: hidden;
          display: grid;
          grid-template-rows: auto auto 1fr auto;
          gap: 16px;
          box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.06);
        }

        .creative-artboard.compact {
          min-height: 360px;
          padding: 18px;
          border-radius: 22px;
        }

        .creative-artboard.editable {
          width: min(560px, 100%);
          aspect-ratio: 1 / 1;
        }

        .creative-artboard::before,
        .creative-artboard::after {
          content: '';
          position: absolute;
          inset: auto;
          border-radius: 999px;
          filter: blur(0px);
          opacity: 0.8;
        }

        .creative-artboard::before {
          width: 220px;
          height: 220px;
          top: -80px;
          right: -40px;
          background: radial-gradient(circle, rgba(234, 179, 8, 0.25), transparent 72%);
        }

        .creative-artboard::after {
          width: 200px;
          height: 200px;
          left: -70px;
          bottom: -60px;
          background: radial-gradient(circle, rgba(96, 165, 250, 0.22), transparent 72%);
        }

        .creative-artboard-badge,
        .creative-artboard-logo,
        .creative-artboard-cta {
          justify-self: start;
          border-radius: 999px;
          padding: 7px 12px;
          font-size: 12px;
          font-weight: 800;
          letter-spacing: 0.04em;
        }

        .creative-artboard-badge {
          background: rgba(255, 255, 255, 0.08);
        }

        .creative-artboard-logo {
          background: linear-gradient(135deg, rgba(248, 250, 252, 0.16), rgba(255, 255, 255, 0.05));
          margin-top: -6px;
        }

        .creative-artboard-copy {
          position: relative;
          z-index: 1;
        }

        .creative-artboard-copy h3 {
          margin: 0;
          font-size: clamp(32px, 4vw, 56px);
          line-height: 0.96;
          text-transform: uppercase;
          letter-spacing: -0.04em;
          max-width: 8ch;
        }

        .creative-artboard-copy p {
          margin: 10px 0 0;
          max-width: 28ch;
          color: rgba(255, 255, 255, 0.72);
          font-size: 15px;
        }

        .creative-artboard-hoodies {
          display: flex;
          align-items: end;
          justify-content: center;
          gap: 10px;
          padding: 6px 0 10px;
          z-index: 1;
        }

        .hoodie {
          width: 82px;
          height: 118px;
          border-radius: 24px 24px 32px 32px;
          position: relative;
          box-shadow:
            inset 0 -10px 20px rgba(0, 0, 0, 0.18),
            0 18px 24px rgba(0, 0, 0, 0.22);
        }

        .hoodie::before {
          content: '';
          position: absolute;
          width: 46px;
          height: 34px;
          left: 50%;
          top: -12px;
          transform: translateX(-50%);
          border-radius: 999px 999px 18px 18px;
          background: inherit;
          box-shadow: inset 0 -6px 10px rgba(0, 0, 0, 0.14);
        }

        .hoodie-gold {
          background: linear-gradient(180deg, #fbbf24, #d97706);
        }

        .hoodie-green {
          background: linear-gradient(180deg, #86efac, #16a34a);
        }

        .hoodie-red {
          background: linear-gradient(180deg, #fca5a5, #dc2626);
        }

        .hoodie-blue {
          background: linear-gradient(180deg, #93c5fd, #2563eb);
        }

        .creative-artboard-footer {
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: 12px;
          z-index: 1;
        }

        .creative-artboard-brand {
          text-transform: uppercase;
          font-size: 12px;
          color: rgba(255, 255, 255, 0.68);
          letter-spacing: 0.16em;
        }

        .creative-artboard-cta {
          background: white;
          color: #111827;
        }

        .editor-primary-actions {
          justify-content: stretch;
        }

        .editor-primary-actions .ghost-btn {
          flex: 1 1 0;
        }

        .editor-accordion {
          border: 1px solid var(--line);
          border-radius: 14px;
          background: rgba(255, 255, 255, 0.02);
          overflow: hidden;
        }

        .editor-accordion summary {
          list-style: none;
          cursor: pointer;
          padding: 14px 16px;
          font-weight: 700;
        }

        .editor-accordion summary::-webkit-details-marker {
          display: none;
        }

        .editor-accordion-body {
          padding: 0 16px 16px;
          display: grid;
          gap: 12px;
        }

        /* FX Controls */
        .fx-grid {
          gap: 10px;
        }

        .fx-label {
          display: grid;
          grid-template-columns: 1fr auto;
          grid-template-rows: auto auto;
          gap: 4px 8px;
          font-size: 12px;
          font-weight: 600;
          color: var(--muted);
        }

        .fx-label span {
          font-size: 11px;
          color: var(--fg);
          font-variant-numeric: tabular-nums;
          justify-self: end;
        }

        .fx-label input[type='range'] {
          grid-column: 1 / -1;
          width: 100%;
          accent-color: var(--brand);
          cursor: pointer;
          height: 4px;
        }

        .fx-color-row {
          display: flex;
          align-items: center;
          justify-content: space-between;
          font-size: 12px;
          font-weight: 600;
          color: var(--muted);
        }

        .fx-color-input {
          width: 36px;
          height: 28px;
          border: 1px solid var(--line);
          border-radius: 8px;
          padding: 2px;
          background: transparent;
          cursor: pointer;
        }

        .fx-reset-btn {
          border: 1px solid var(--line);
          border-radius: 8px;
          background: transparent;
          color: var(--muted);
          font-size: 12px;
          font-weight: 700;
          padding: 6px 12px;
          cursor: pointer;
          justify-self: start;
        }

        .fx-reset-btn:hover {
          border-color: color-mix(in oklab, var(--brand) 55%, var(--line));
          color: var(--fg);
        }

        .artboard-overlay {
          position: absolute;
          inset: 0;
          border-radius: inherit;
          pointer-events: none;
          z-index: 1;
        }

        /* ÔöÇÔöÇ Advanced Panels ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */
        .advanced-panel {
          margin-top: 12px;
          border: 1px solid var(--line);
          border-radius: 16px;
          overflow: hidden;
          background: color-mix(in oklab, var(--bg-soft) 96%, white 4%);
        }

        .adv-panel-head {
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: 16px;
          flex-wrap: wrap;
          padding: 16px 20px 12px;
          border-bottom: 1px solid var(--line);
        }

        .adv-panel-title {
          font-size: 15px;
          font-weight: 800;
          margin: 0;
          letter-spacing: -0.01em;
        }

        .adv-panel-actions {
          display: flex;
          align-items: center;
          gap: 16px;
          flex-wrap: wrap;
        }

        .adv-snap-label {
          display: inline-flex;
          align-items: center;
          gap: 8px;
          flex-direction: row;
          font-size: 12px;
          font-weight: 700;
          color: var(--muted);
        }

        .adv-panel-body {
          padding: 4px 0 0;
        }

        .adv-info-text {
          font-size: 12px;
          color: var(--muted);
          margin: 0;
        }

        /* Timeline */
        .timeline-shell {
          display: grid;
          gap: 0;
        }

        .timeline-ruler {
          position: relative;
          height: 28px;
          background: color-mix(in oklab, var(--bg-soft) 94%, black 6%);
          border-bottom: 1px solid var(--line);
          margin: 0 0 0 140px;
        }

        .timeline-ruler-mark {
          position: absolute;
          top: 6px;
          transform: translateX(-50%);
          font-size: 10px;
          color: var(--muted);
          font-variant-numeric: tabular-nums;
          pointer-events: none;
        }

        .timeline-playhead {
          position: absolute;
          top: 0;
          bottom: 0;
          width: 2px;
          background: #ef4444;
          transform: translateX(-50%);
          z-index: 2;
        }

        .timeline-tracks {
          display: grid;
          gap: 0;
        }

        .timeline-track {
          display: grid;
          grid-template-columns: 140px minmax(0, 1fr);
          border-bottom: 1px solid var(--line);
          min-height: 44px;
        }

        .timeline-track.selected .timeline-track-header {
          background: color-mix(in oklab, var(--brand) 12%, transparent);
        }

        .timeline-track-header {
          display: flex;
          align-items: center;
          justify-content: space-between;
          padding: 6px 10px;
          border-right: 1px solid var(--line);
          border-left: 3px solid transparent;
          gap: 6px;
          background: color-mix(in oklab, var(--bg-soft) 98%, white 2%);
        }

        .timeline-track-name {
          font-size: 12px;
          font-weight: 700;
          background: transparent;
          border: 0;
          color: var(--fg);
          cursor: pointer;
          text-align: left;
          padding: 0;
        }

        .timeline-track-controls {
          display: flex;
          gap: 4px;
        }

        .tl-ctrl-btn {
          border: 0;
          background: transparent;
          font-size: 13px;
          cursor: pointer;
          padding: 2px;
          border-radius: 4px;
          opacity: 0.5;
          line-height: 1;
        }

        .tl-ctrl-btn.active,
        .tl-ctrl-btn:hover {
          opacity: 1;
          background: color-mix(in oklab, var(--brand) 14%, transparent);
        }

        .timeline-lane {
          position: relative;
          overflow: hidden;
          background: color-mix(in oklab, var(--bg-soft) 96%, transparent);
        }

        .timeline-clip {
          position: absolute;
          top: 8px;
          bottom: 8px;
          border-radius: 6px;
          opacity: 0.5;
        }

        .timeline-keyframe {
          position: absolute;
          top: 50%;
          transform: translate(-50%, -50%) rotate(45deg);
          width: 10px;
          height: 10px;
          border-radius: 2px;
          z-index: 2;
          cursor: pointer;
        }

        .timeline-kf-panel {
          padding: 14px 16px;
          border-top: 1px solid var(--line);
          display: grid;
          gap: 12px;
        }

        .timeline-kf-panel h4 {
          font-size: 12px;
          font-weight: 700;
          color: var(--muted);
          margin: 0;
        }

        .timeline-kf-row {
          display: flex;
          align-items: flex-end;
          gap: 14px;
          flex-wrap: wrap;
        }

        /* RGB Curves */
        .curve-preview {
          background: rgba(0, 0, 0, 0.3);
          border-radius: 10px;
          padding: 8px;
        }

        .curve-svg {
          width: 100%;
          height: 80px;
          display: block;
        }

        .range-red {
          accent-color: #ef4444;
        }
        .range-green {
          accent-color: #10b981;
        }
        .range-blue {
          accent-color: #3b82f6;
        }

        /* Color Wheels */
        .color-wheels-row {
          display: grid;
          grid-template-columns: repeat(3, minmax(0, 1fr));
          gap: 12px;
        }

        .color-wheel-item {
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 6px;
        }

        .color-wheel-ring {
          width: 60px;
          height: 60px;
          border-radius: 50%;
          background: conic-gradient(#ef4444, #f59e0b, #10b981, #3b82f6, #8b5cf6, #ef4444);
          display: grid;
          place-items: center;
          box-shadow: inset 0 0 0 6px color-mix(in oklab, var(--bg-soft) 96%, transparent);
        }

        .color-wheel-val {
          font-size: 11px;
          font-weight: 800;
          font-variant-numeric: tabular-nums;
          color: var(--fg);
          background: color-mix(in oklab, var(--bg-soft) 90%, transparent);
          border-radius: 999px;
          padding: 1px 5px;
        }

        .color-wheel-label {
          font-size: 11px;
          font-weight: 700;
          color: var(--muted);
        }

        .color-wheel-range {
          width: 100%;
        }

        /* Transitions */
        .transition-grid {
          display: flex;
          flex-wrap: wrap;
          gap: 8px;
        }

        .transition-chip {
          border: 1px solid var(--line);
          border-radius: 8px;
          background: color-mix(in oklab, var(--bg-soft) 96%, white 4%);
          color: var(--fg);
          font-size: 12px;
          font-weight: 600;
          padding: 6px 12px;
          cursor: pointer;
          white-space: nowrap;
        }

        .transition-chip.active {
          border-color: color-mix(in oklab, var(--brand) 70%, var(--line));
          background: color-mix(in oklab, var(--brand) 16%, transparent);
          color: var(--fg);
        }

        .transition-chip:hover {
          border-color: color-mix(in oklab, var(--brand) 50%, var(--line));
        }

        /* Subtitle editor */
        .subtitle-list {
          display: grid;
          gap: 8px;
        }

        .subtitle-row {
          display: grid;
          grid-template-columns: 90px minmax(0, 1fr) auto;
          align-items: center;
          gap: 8px;
        }

        .subtitle-time {
          font-size: 11px;
          font-weight: 700;
          color: var(--muted);
          font-variant-numeric: tabular-nums;
          white-space: nowrap;
        }

        .subtitle-input {
          border: 1px solid var(--line);
          border-radius: 8px;
          background: color-mix(in oklab, var(--bg-soft) 98%, white 2%);
          color: var(--fg);
          font: inherit;
          font-size: 13px;
          padding: 6px 10px;
        }

        /* Version history */
        .version-list {
          display: grid;
          gap: 8px;
        }

        .version-row {
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: 12px;
          border: 1px solid var(--line);
          border-radius: 10px;
          padding: 10px 12px;
          background: color-mix(in oklab, var(--bg-soft) 98%, white 2%);
        }

        .version-row.active {
          border-color: color-mix(in oklab, var(--brand) 70%, var(--line));
          background: color-mix(in oklab, var(--brand) 10%, transparent);
        }

        .version-meta {
          display: flex;
          flex-direction: column;
          gap: 2px;
        }

        .version-meta strong {
          font-size: 13px;
          font-weight: 700;
        }

        .version-meta span {
          font-size: 11px;
          color: var(--muted);
        }

        .editor-toggle-row {
          grid-template-columns: minmax(0, 1fr) auto;
          align-items: center;
        }

        .publish-toolbar {
          margin: 0 0 10px;
          border: 1px solid var(--line);
          border-radius: 14px;
          background: color-mix(in oklab, var(--bg-soft) 98%, white 2%);
          box-shadow: 0 12px 34px rgba(0, 0, 0, 0.17);
          display: grid;
          grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, 1fr) auto;
          align-items: end;
          gap: 10px;
          padding: 10px;
        }

        .publish-mode-switch {
          display: grid;
          grid-template-columns: repeat(2, minmax(0, 1fr));
          gap: 6px;
        }

        .publish-toolbar label {
          color: var(--muted);
          font-size: 12px;
          font-weight: 700;
        }

        .publish-toolbar input {
          margin-top: 6px;
          width: 100%;
          border: 1px solid var(--line);
          border-radius: 10px;
          background: rgba(0, 0, 0, 0.1);
          color: var(--fg);
          padding: 9px 10px;
          font: inherit;
        }

        .tool-rail,
        .template-panel,
        .canvas-zone,
        .property-panel {
          border: 1px solid var(--line);
          border-radius: 14px;
          background: color-mix(in oklab, var(--bg-soft) 98%, white 2%);
          box-shadow: 0 12px 34px rgba(0, 0, 0, 0.17);
        }

        .tool-rail {
          padding: 10px 8px;
          display: grid;
          gap: 8px;
        }

        .rail-btn {
          border: 1px solid var(--line);
          border-radius: 10px;
          padding: 8px 6px;
          background: transparent;
          color: var(--muted);
          cursor: pointer;
          display: grid;
          justify-items: center;
          gap: 4px;
          font-size: 11px;
          font-weight: 700;
          text-transform: capitalize;
        }

        .rail-btn .dot {
          width: 10px;
          height: 10px;
          border-radius: 50%;
          background: color-mix(in oklab, var(--brand) 40%, transparent);
        }

        .rail-btn.active {
          border-color: color-mix(in oklab, var(--brand) 65%, var(--line));
          color: var(--fg);
          background: color-mix(in oklab, var(--brand) 15%, transparent);
        }

        .template-panel {
          padding: 12px;
          display: grid;
          gap: 10px;
          max-height: 78vh;
          overflow: auto;
        }

        .panel-head h2 {
          margin: 0;
          font-size: 20px;
        }

        .panel-copy {
          margin: 6px 0 0;
          color: var(--muted);
          font-size: 12px;
          line-height: 1.5;
        }

        .asset-switch,
        .panel-tabs {
          display: grid;
          grid-template-columns: repeat(3, minmax(0, 1fr));
          gap: 6px;
        }

        .panel-tabs {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .chip {
          border: 1px solid var(--line);
          border-radius: 10px;
          padding: 7px 8px;
          background: transparent;
          color: var(--muted);
          font-weight: 700;
          cursor: pointer;
          font-size: 12px;
        }

        .chip.active {
          color: var(--fg);
          border-color: color-mix(in oklab, var(--brand) 70%, var(--line));
          background: color-mix(in oklab, var(--brand) 20%, transparent);
        }

        .search-wrap input,
        .property-group input,
        .property-group select,
        .property-group textarea {
          width: 100%;
          border: 1px solid var(--line);
          border-radius: 10px;
          background: rgba(0, 0, 0, 0.1);
          color: var(--fg);
          padding: 9px 10px;
          font: inherit;
          margin-top: 6px;
        }

        .checkbox-row {
          display: inline-flex;
          align-items: center;
          gap: 8px;
          font-size: 13px;
          color: var(--muted);
        }

        .library-stats-row {
          display: flex;
          flex-wrap: wrap;
          gap: 8px;
        }

        .library-stat-chip {
          display: inline-flex;
          align-items: center;
          border-radius: 999px;
          padding: 6px 10px;
          background: color-mix(in oklab, var(--brand) 16%, transparent);
          color: var(--fg);
          font-size: 11px;
          font-weight: 700;
        }

        .library-stat-chip.muted {
          background: rgba(255, 255, 255, 0.04);
          color: var(--muted);
        }

        .template-grid {
          display: grid;
          grid-template-columns: 1fr;
          gap: 12px;
        }

        .template-card {
          border: 1px solid var(--line);
          border-radius: 18px;
          overflow: hidden;
          background: rgba(255, 255, 255, 0.03);
          display: grid;
          gap: 0;
        }

        .template-preview {
          min-height: 164px;
          padding: 14px;
          display: grid;
          align-content: space-between;
          color: white;
        }

        .template-preview-head {
          display: flex;
          justify-content: space-between;
          gap: 8px;
        }

        .template-preview-body {
          display: grid;
          gap: 6px;
        }

        .template-preview-body strong,
        .template-card-copy strong {
          font-size: 14px;
          line-height: 1.1;
        }

        .template-preview-body span,
        .template-card-copy span {
          font-size: 12px;
          line-height: 1.5;
        }

        .template-badge {
          display: inline-flex;
          align-items: center;
          border-radius: 999px;
          padding: 5px 8px;
          background: rgba(15, 23, 42, 0.28);
          color: white;
          font-size: 10px;
          font-weight: 800;
          letter-spacing: 0.06em;
          text-transform: uppercase;
        }

        .template-badge.subtle {
          background: rgba(255, 255, 255, 0.16);
        }

        .template-card-body {
          padding: 12px;
          display: grid;
          gap: 12px;
        }

        .template-card-copy {
          display: grid;
          gap: 6px;
          color: var(--fg);
        }

        .template-card-copy span {
          color: var(--muted);
        }

        .template-card-actions {
          display: grid;
          grid-template-columns: repeat(2, minmax(0, 1fr));
          gap: 8px;
        }

        .template-card.active {
          border-color: color-mix(in oklab, var(--brand) 68%, var(--line));
          box-shadow: 0 0 0 2px color-mix(in oklab, var(--brand) 28%, transparent);
        }

        .template-customizer {
          border: 1px solid var(--line);
          border-radius: 16px;
          padding: 12px;
          display: grid;
          gap: 10px;
          background: color-mix(in oklab, var(--bg-soft) 98%, white 2%);
        }

        .template-customizer-head {
          display: flex;
          justify-content: space-between;
          align-items: start;
          gap: 10px;
        }

        .template-customizer-head h3 {
          margin: 4px 0 0;
          font-size: 16px;
        }

        .template-customizer-kicker {
          margin: 0;
          font-size: 11px;
          font-weight: 800;
          letter-spacing: 0.08em;
          text-transform: uppercase;
          color: var(--muted);
        }

        .template-customizer-tag {
          border-radius: 999px;
          padding: 6px 10px;
          background: color-mix(in oklab, var(--brand) 14%, transparent);
          color: var(--fg);
          font-size: 11px;
          font-weight: 700;
        }

        .template-customizer-row {
          display: grid;
          grid-template-columns: repeat(2, minmax(0, 1fr));
          gap: 10px;
        }

        .empty {
          grid-column: 1 / -1;
          color: var(--muted);
          margin: 0;
          font-size: 13px;
        }

        .canvas-zone {
          padding: 10px;
          display: grid;
          gap: 10px;
        }

        .canvas-toolbar {
          display: inline-flex;
          gap: 8px;
          flex-wrap: wrap;
          align-items: center;
        }

        .spacer {
          flex: 1;
        }

        .canvas-board {
          min-height: 620px;
          border-radius: 12px;
          border: 1px solid var(--line);
          background-color: #eef5ff;
          position: relative;
          overflow: hidden;
          padding: 30px 28px;
          display: grid;
          grid-template-rows: auto auto auto auto 1fr;
          align-content: start;
        }

        .brand {
          color: #1d4ed8;
          font-weight: 800;
          letter-spacing: 0.01em;
          font-size: 28px;
        }

        .headline {
          margin-top: 24px;
          font-size: clamp(44px, 7vw, 86px);
          line-height: 0.92;
          font-weight: 900;
          max-width: 62%;
          text-transform: uppercase;
        }

        .subheadline {
          margin: 10px 0 0;
          color: #1f2937;
          font-weight: 600;
          font-size: 21px;
          max-width: 58%;
        }

        .cta {
          margin-top: 14px;
          border: 0;
          background: #1d4ed8;
          color: white;
          border-radius: 999px;
          padding: 11px 18px;
          font-weight: 700;
          width: fit-content;
        }

        .uploaded-image,
        .image-placeholder {
          position: absolute;
          right: 20px;
          bottom: 20px;
          width: 42%;
          height: 66%;
          border-radius: 14px;
          border: 2px solid rgba(29, 78, 216, 0.2);
          object-fit: cover;
          background: rgba(255, 255, 255, 0.5);
          display: grid;
          place-items: center;
          color: #4b5563;
          font-weight: 700;
        }

        .coin {
          position: absolute;
          width: 74px;
          height: 74px;
          border-radius: 50%;
          background: radial-gradient(circle at 30% 25%, #fef3c7, #f59e0b 70%);
          box-shadow: 0 12px 18px rgba(245, 158, 11, 0.28);
        }

        .coin-a {
          right: 34%;
          top: 44%;
        }

        .coin-b {
          right: 9%;
          top: 27%;
        }

        .carousel-strip {
          display: flex;
          gap: 8px;
          overflow: auto;
          padding-bottom: 2px;
        }

        .slide-chip {
          border: 1px solid var(--line);
          border-radius: 999px;
          background: transparent;
          color: var(--muted);
          font-weight: 700;
          padding: 7px 11px;
          white-space: nowrap;
          cursor: pointer;
        }

        .slide-chip.active {
          color: var(--fg);
          border-color: color-mix(in oklab, var(--brand) 70%, var(--line));
          background: color-mix(in oklab, var(--brand) 20%, transparent);
        }

        .property-panel {
          padding: 12px;
          display: grid;
          gap: 10px;
          max-height: 78vh;
          overflow: auto;
        }

        .property-group {
          border: 1px solid var(--line);
          border-radius: 12px;
          padding: 10px;
          display: grid;
          gap: 8px;
        }

        .property-group h3 {
          margin: 0;
          font-size: 14px;
          color: var(--muted);
          text-transform: uppercase;
          letter-spacing: 0.06em;
        }

        .property-group label {
          font-size: 12px;
          color: var(--muted);
        }

        .align-row {
          display: grid;
          grid-template-columns: repeat(4, minmax(0, 1fr));
          gap: 6px;
        }

        .ghost-btn {
          border: 1px solid var(--line);
          border-radius: 10px;
          background: transparent;
          color: var(--fg);
          padding: 8px 10px;
          font-weight: 700;
          cursor: pointer;
        }

        .ghost-btn.danger {
          border-color: rgba(239, 68, 68, 0.55);
          color: #ef4444;
        }

        .publish-btn {
          border: 0;
          border-radius: 10px;
          background: linear-gradient(120deg, #2563eb, #1d4ed8);
          color: white;
          font-weight: 800;
          padding: 10px 16px;
          cursor: pointer;
        }

        .insights-shell {
          margin: 0 0 12px;
          border: 1px solid color-mix(in oklab, var(--brand) 25%, var(--line));
          border-radius: 18px;
          padding: 16px;
          background:
            radial-gradient(circle at top left, rgba(96, 165, 250, 0.26), transparent 34%),
            linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(236, 245, 255, 0.98));
          box-shadow: 0 20px 45px rgba(30, 41, 59, 0.12);
          color: #0f172a;
          display: grid;
          gap: 14px;
        }

        .insights-head {
          display: flex;
          align-items: start;
          justify-content: space-between;
          gap: 12px;
        }

        .insights-eyebrow {
          margin: 0 0 6px;
          color: #2563eb;
          font-size: 11px;
          font-weight: 800;
          letter-spacing: 0.14em;
          text-transform: uppercase;
        }

        .insights-head h2 {
          margin: 0;
          font-size: 28px;
          line-height: 1.05;
        }

        .insights-copy {
          margin: 8px 0 0;
          color: #475569;
          max-width: 720px;
        }

        .insights-grid {
          display: grid;
          grid-template-columns: 1.15fr 1fr 0.9fr 0.9fr;
          gap: 12px;
        }

        .insight-card {
          border: 1px solid rgba(148, 163, 184, 0.25);
          border-radius: 18px;
          padding: 16px;
          background: rgba(255, 255, 255, 0.92);
          box-shadow: 0 12px 26px rgba(37, 99, 235, 0.08);
          display: grid;
          gap: 10px;
          min-height: 188px;
        }

        .insight-card-traction {
          background: linear-gradient(180deg, rgba(238, 248, 255, 0.98), rgba(255, 255, 255, 0.94));
        }

        .insight-card-roi {
          background: linear-gradient(180deg, rgba(236, 253, 245, 0.98), rgba(255, 255, 255, 0.94));
        }

        .insight-card-post {
          background: linear-gradient(180deg, rgba(239, 246, 255, 0.98), rgba(255, 255, 255, 0.94));
          align-content: start;
        }

        .insight-label {
          margin: 0;
          font-size: 12px;
          font-weight: 800;
          letter-spacing: 0.08em;
          text-transform: uppercase;
          color: #64748b;
        }

        .insight-value,
        .insight-title {
          margin: 0;
          font-size: clamp(24px, 3vw, 38px);
          line-height: 1;
          color: #0f172a;
        }

        .insight-title {
          font-size: 24px;
        }

        .insight-subtle,
        .insight-copy-card {
          margin: 0;
          color: #475569;
          font-size: 13px;
          line-height: 1.5;
        }

        .trend-bars {
          display: grid;
          grid-template-columns: repeat(8, minmax(0, 1fr));
          align-items: end;
          gap: 8px;
          min-height: 104px;
          margin-top: auto;
        }

        .trend-bar-wrap {
          display: grid;
          justify-items: center;
          gap: 6px;
        }

        .trend-bar {
          width: 100%;
          border-radius: 999px 999px 10px 10px;
          background: linear-gradient(180deg, #2563eb, #60a5fa);
          min-height: 12px;
        }

        .trend-bar-wrap span {
          font-size: 10px;
          font-weight: 700;
          color: #94a3b8;
        }

        .metric-pair-grid {
          display: grid;
          grid-template-columns: repeat(2, minmax(0, 1fr));
          gap: 10px;
          margin-top: auto;
        }

        .metric-pair {
          border: 1px solid rgba(148, 163, 184, 0.22);
          border-radius: 14px;
          padding: 10px;
          background: rgba(248, 250, 252, 0.92);
          display: grid;
          gap: 4px;
        }

        .metric-pair span {
          font-size: 11px;
          color: #64748b;
          text-transform: uppercase;
          letter-spacing: 0.06em;
          font-weight: 700;
        }

        .metric-pair strong {
          font-size: 18px;
          color: #0f172a;
        }

        .insight-pill-row {
          display: flex;
          flex-wrap: wrap;
          gap: 8px;
          margin-top: auto;
        }

        .insight-pill {
          display: inline-flex;
          align-items: center;
          border-radius: 999px;
          padding: 8px 12px;
          background: rgba(15, 23, 42, 0.06);
          color: #0f172a;
          font-size: 12px;
          font-weight: 800;
        }

        .insight-pill.positive {
          background: rgba(16, 185, 129, 0.16);
          color: #047857;
        }

        .insight-post-meta {
          display: flex;
          flex-wrap: wrap;
          gap: 8px;
          margin-top: auto;
        }

        .insight-post-meta span {
          border-radius: 999px;
          padding: 7px 10px;
          background: rgba(37, 99, 235, 0.08);
          color: #1d4ed8;
          font-size: 12px;
          font-weight: 700;
        }

        .insight-empty {
          margin: auto 0;
          grid-column: 1 / -1;
          color: #94a3b8;
          font-size: 12px;
        }

        /* Topbar enhancements */
        .topbar-left {
          display: flex;
          align-items: center;
          gap: 8px;
        }

        .topbar-right {
          display: flex;
          align-items: center;
          gap: 8px;
        }

        .topbar-back-btn {
          border: 1px solid var(--line);
          border-radius: 10px;
          background: transparent;
          color: var(--fg);
          padding: 8px 12px;
          font-weight: 700;
          cursor: pointer;
          text-decoration: none;
          font-size: 13px;
          display: inline-flex;
          align-items: center;
        }

        .topbar-save-btn {
          font-size: 13px;
        }

        .topbar-icon-btn {
          padding: 8px 12px;
          font-size: 16px;
        }

        .topbar-send-btn {
          border: 0;
          border-radius: 10px;
          background: linear-gradient(120deg, #2563eb, #1d4ed8);
          color: white;
          font-weight: 800;
          padding: 9px 14px;
          cursor: pointer;
          font-size: 15px;
        }

        .topbar-send-btn:disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }

        .topbar-promo-btn {
          border: 0;
          border-radius: 10px;
          background: linear-gradient(120deg, #1e3a8a, #1d4ed8);
          color: white;
          font-weight: 800;
          padding: 9px 14px;
          cursor: pointer;
          font-size: 13px;
          display: flex;
          align-items: center;
          gap: 6px;
        }

        .topbar-promo-timer {
          font-variant-numeric: tabular-nums;
          letter-spacing: 0.02em;
        }

        /* Captions */
        .captions-shell {
          margin-top: 12px;
          border: 1px solid var(--line);
          border-radius: 14px;
          padding: 20px;
          background: color-mix(in oklab, var(--bg-soft) 96%, white 4%);
          display: grid;
          gap: 16px;
        }

        .captions-topbar {
          display: flex;
          align-items: flex-end;
          justify-content: flex-start;
          gap: 14px;
          flex-wrap: wrap;
        }

        .captions-style-shell {
          border: 1px solid var(--line);
          border-radius: 12px;
          padding: 14px;
          background: color-mix(in oklab, var(--bg-soft) 97%, white 3%);
          display: grid;
          gap: 12px;
        }

        .captions-style-header {
          display: grid;
          gap: 4px;
        }

        .captions-style-header h3,
        .captions-style-header p {
          margin: 0;
        }

        .captions-style-kicker {
          margin: 0;
          font-size: 11px;
          text-transform: uppercase;
          letter-spacing: 0.08em;
          color: var(--muted);
          font-weight: 700;
        }

        .captions-style-categories {
          display: flex;
          gap: 8px;
          flex-wrap: wrap;
        }

        .ugc-style-chip {
          border: 1px solid var(--line);
          border-radius: 999px;
          background: color-mix(in oklab, var(--bg-soft) 95%, white 5%);
          color: var(--fg);
          padding: 6px 12px;
          font-size: 12px;
          font-weight: 700;
          cursor: pointer;
        }

        .ugc-style-chip.active {
          border-color: color-mix(in oklab, var(--brand) 70%, var(--line));
          background: color-mix(in oklab, var(--brand) 20%, transparent);
        }

        .explore-chip {
          border-style: dashed;
        }

        .ugc-preview-head {
          display: grid;
          gap: 2px;
        }

        .ugc-preview-head strong {
          font-size: 13px;
        }

        .ugc-preview-head span {
          font-size: 12px;
          color: var(--muted);
        }

        .captions-sync-error {
          color: #ef4444;
          font-weight: 700;
        }

        .ugc-preview-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
          gap: 10px;
        }

        .ugc-preview-card {
          border: 1px solid var(--line);
          border-radius: 12px;
          padding: 10px;
          display: grid;
          gap: 8px;
          background: color-mix(in oklab, var(--bg-soft) 95%, white 5%);
        }

        .ugc-preview-card.active {
          border-color: color-mix(in oklab, var(--brand) 72%, var(--line));
          background: color-mix(in oklab, var(--brand) 15%, transparent);
        }

        .ugc-preview-card p {
          margin: 0;
          font-size: 12px;
          color: var(--muted);
        }

        .ugc-preview-meta {
          display: flex;
          justify-content: space-between;
          font-size: 11px;
          color: var(--muted);
          font-weight: 700;
          text-transform: uppercase;
          letter-spacing: 0.06em;
        }

        .ugc-preview-footer {
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: 8px;
          font-size: 12px;
          font-weight: 700;
        }

        .captions-control-label {
          display: flex;
          flex-direction: column;
          gap: 6px;
          font-size: 12px;
          font-weight: 700;
          color: var(--muted);
        }

        .captions-select {
          border: 1px solid var(--line);
          border-radius: 10px;
          background: color-mix(in oklab, var(--bg-soft) 98%, white 2%);
          color: var(--fg);
          padding: 8px 28px 8px 10px;
          font: inherit;
          font-size: 13px;
          cursor: pointer;
        }

        .captions-generate-btn {
          border: 1px solid color-mix(in oklab, var(--brand) 70%, var(--line));
          border-radius: 10px;
          background: color-mix(in oklab, var(--brand) 16%, transparent);
          color: var(--fg);
          font-weight: 700;
          padding: 9px 18px;
          cursor: pointer;
          font-size: 13px;
          align-self: flex-end;
        }

        .captions-generate-btn-strong {
          background: linear-gradient(120deg, #0f766e, #0ea5a4);
          border-color: color-mix(in oklab, #0f766e 65%, var(--line));
          color: white;
        }

        .captions-generate-btn:disabled {
          opacity: 0.55;
          cursor: not-allowed;
        }

        .captions-pack-description {
          font-size: 12px;
          color: var(--muted);
          font-weight: 600;
          max-width: 320px;
          align-self: center;
        }

        .captions-video-config-note {
          font-size: 12px;
          color: var(--muted);
          font-weight: 600;
          border: 1px solid var(--line);
          border-radius: 10px;
          padding: 8px 10px;
          background: color-mix(in oklab, var(--bg-soft) 97%, white 3%);
          align-self: center;
        }

        .captions-preset-row {
          display: flex;
          align-items: center;
          gap: 8px;
          align-self: flex-end;
          border: 0;
          margin: 0;
          padding: 0;
        }

        .captions-sr-only {
          position: absolute;
          width: 1px;
          height: 1px;
          padding: 0;
          margin: -1px;
          overflow: hidden;
          clip: rect(0, 0, 0, 0);
          white-space: nowrap;
          border: 0;
        }

        .captions-preset-btn {
          border: 1px solid var(--line);
          border-radius: 999px;
          background: color-mix(in oklab, var(--bg-soft) 96%, white 4%);
          color: var(--fg);
          font-size: 12px;
          font-weight: 700;
          padding: 6px 11px;
          cursor: pointer;
        }

        .captions-preset-btn:hover {
          border-color: color-mix(in oklab, var(--brand) 58%, var(--line));
          background: color-mix(in oklab, var(--brand) 16%, transparent);
        }

        .captions-platform-preset-row {
          display: flex;
          flex-wrap: wrap;
          align-items: center;
          gap: 8px;
          max-width: 620px;
        }

        .captions-preset-btn-platform {
          border-style: dashed;
        }

        .captions-toggle-label {
          display: inline-flex;
          align-items: center;
          justify-content: space-between;
          gap: 10px;
          min-width: 120px;
          border: 1px solid var(--line);
          border-radius: 10px;
          padding: 8px 10px;
          background: color-mix(in oklab, var(--bg-soft) 98%, white 2%);
        }

        .captions-list {
          display: grid;
          gap: 14px;
        }

        .captions-item {
          border: 1px solid var(--line);
          border-radius: 14px;
          background: color-mix(in oklab, var(--bg-soft) 98%, white 2%);
          display: grid;
          grid-template-columns: 40px minmax(0, 1fr);
          overflow: hidden;
        }

        .captions-item.selected {
          border-color: color-mix(in oklab, #10b981 70%, var(--line));
        }

        .captions-check {
          display: flex;
          align-items: flex-start;
          justify-content: center;
          padding: 16px 8px;
          background: transparent;
          border: 0;
          border-right: 1px solid var(--line);
          color: #10b981;
          font-size: 20px;
          font-weight: 900;
          cursor: pointer;
          min-height: 52px;
        }

        .captions-item.selected .captions-check {
          background: color-mix(in oklab, #10b981 16%, transparent);
        }

        .captions-textarea-wrap {
          display: grid;
        }

        .captions-textarea {
          width: 100%;
          border: 0;
          background: transparent;
          color: var(--fg);
          padding: 14px 14px 8px;
          font: inherit;
          font-size: 14px;
          line-height: 1.7;
          resize: none;
          min-height: 90px;
        }

        .captions-footer {
          display: flex;
          align-items: center;
          justify-content: flex-end;
          gap: 10px;
          padding: 6px 12px 10px;
          border-top: 1px solid var(--line);
        }

        .captions-char-count {
          font-size: 11px;
          color: var(--muted);
          font-weight: 600;
          margin-left: auto;
        }

        .captions-emoji-btn {
          border: 0;
          background: transparent;
          font-size: 20px;
          cursor: pointer;
          padding: 2px 4px;
          border-radius: 6px;
          line-height: 1;
        }

        .captions-emoji-btn:hover {
          background: color-mix(in oklab, var(--brand) 12%, transparent);
        }

        /* Hashtags */
        .hashtags-shell {
          margin-top: 12px;
          border: 1px solid var(--line);
          border-radius: 14px;
          padding: 16px;
          background: color-mix(in oklab, var(--bg-soft) 96%, white 4%);
          display: grid;
          gap: 0;
        }

        .hashtags-topbar {
          display: grid;
          grid-template-columns: auto 1fr auto;
          align-items: center;
          gap: 24px;
          padding-bottom: 14px;
          border-bottom: 1px solid var(--line);
          margin-bottom: 16px;
        }

        .hashtags-by-group,
        .hashtags-sort-group {
          display: flex;
          align-items: center;
          gap: 12px;
        }

        .hashtags-group-label {
          font-size: 12px;
          font-weight: 800;
          color: var(--muted);
          text-transform: uppercase;
          letter-spacing: 0.06em;
          white-space: nowrap;
        }

        .hashtags-radio-label {
          display: flex;
          align-items: center;
          gap: 6px;
          font-size: 13px;
          font-weight: 600;
          color: var(--fg);
          cursor: pointer;
        }

        .hashtags-radio-label input[type='radio'] {
          accent-color: var(--brand);
          width: 15px;
          height: 15px;
          cursor: pointer;
        }

        .hashtags-reload-group {
          display: flex;
          align-items: center;
          gap: 10px;
        }

        .hashtags-reload-btn {
          border: 0;
          background: transparent;
          color: #2563eb;
          font-weight: 700;
          font-size: 13px;
          cursor: pointer;
          padding: 4px 0;
        }

        .hashtags-added-count {
