    <main className="workspace-shell" style={workspaceStyle}>
      <section className="workspace-hero">
        <div>
          <p className="eyebrow">Social Workspace</p>
          <h1>Connect, publish, engage, track competitors, and monitor notifications from one place.</h1>
          <p className="hero-copy">
            OAuth-connected channels, brand details, inbox engagement, traction metrics, competitor monitoring, and
            one-click autoposting.
          </p>
