        <div className="hero-actions">
          <label>
            <span>Tenant</span>
            <input value={tenantId} onChange={(event) => setTenantId(event.target.value)} />
          </label>
          <a href="/studio/editor" className="ghost-link">
            Open Editor
          </a>
        </div>
      </section>

      {successMessage ? <p className="success-banner">{successMessage}</p> : null}
      {error ? <p className="error-banner">{error}</p> : null}

      <section className="kpi-grid">
        <article className="kpi-card">
          <span>Connected</span>
          <strong>{overview?.connected_accounts ?? 0}</strong>
          <small>accounts live</small>
        </article>
        <article className="kpi-card">
          <span>Reach</span>
          <strong>{formatCompactNumber(totalReach)}</strong>
          <small>likes, shares, comments, followers</small>
        </article>
        <article className="kpi-card">
          <span>Inbox</span>
          <strong>{overview?.inbox_open ?? 0}</strong>
          <small>open conversations</small>
        </article>
        <article className="kpi-card">
          <span>Notifications</span>
          <strong>{overview?.notifications_unread ?? 0}</strong>
          <small>unread alerts</small>
        </article>
      </section>

      <section className="tabs-row" aria-label="Workspace tabs">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            type="button"
            className={activeTab === tab.id ? 'tab-btn active' : 'tab-btn'}
            onClick={() => setActiveTab(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </section>

      {activeTab === 'social' ? (
        <SocialTab
          providers={providers} accounts={accounts} accountsByNetwork={accountsByNetwork} connectedChannelCount={connectedChannelCount} connectProvider={connectProvider} connectAllProviders={connectAllProviders} disconnectAccount={disconnectAccount}
        />
      ) : null}

      {activeTab === 'brand' ? (
        <BrandTab
          brandProfile={brandProfile} setBrandProfile={setBrandProfile} isSavingBrand={isSavingBrand} saveBrandProfile={saveBrandProfile} setIsFetchWebsiteModalOpen={setIsFetchWebsiteModalOpen} setIsAvatarModalOpen={setIsAvatarModalOpen} setIsVoiceoverModalOpen={setIsVoiceoverModalOpen} setWebsiteDraft={setWebsiteDraft} handleLogoUpload={handleLogoUpload} updateBrandColor={updateBrandColor} addBrandPaletteColor={addBrandPaletteColor}
        />
      ) : null}

      {activeTab === 'engagement' ? (
        <EngagementTab
          accounts={accounts} inboxStats={inboxStats} messages={messages} replyDrafts={replyDrafts} setReplyDrafts={setReplyDrafts} engageMessage={engageMessage}
        />
      ) : null}

      {activeTab === 'competitors' ? (
        <CompetitorsTab
          competitorReport={competitorReport} shareOfVoice={shareOfVoice} competitorForm={competitorForm} setCompetitorForm={setCompetitorForm} addCompetitor={addCompetitor} syncOwnBrandMetrics={syncOwnBrandMetrics}
        />
      ) : null}

      {activeTab === 'autopost' ? (
        <AutopostTab
          accounts={accounts} autopostForm={autopostForm} setAutopostForm={setAutopostForm} creativeStep={creativeStep} setCreativeStep={setCreativeStep} creativeIdea={creativeIdea} setCreativeIdea={setCreativeIdea} creativeReferenceImage={creativeReferenceImage} creativeReferenceName={creativeReferenceName} handleCreativeReferenceUpload={handleCreativeReferenceUpload} creativeIdeas={creativeIdeas} creativePostType={creativePostType} setCreativePostType={setCreativePostType} creativeAspectRatio={creativeAspectRatio} setCreativeAspectRatio={setCreativeAspectRatio} creativeLibraryFilter={creativeLibraryFilter} setCreativeLibraryFilter={setCreativeLibraryFilter} isCreativeGenerating={isCreativeGenerating} preview={preview} lastPublished={lastPublished} visibleLibraryItems={visibleLibraryItems} setSelectedLibraryId={setSelectedLibraryId} generateCreativeCard={generateCreativeCard} previewAutopost={previewAutopost} publishAutopost={publishAutopost} copyShareLink={copyShareLink} triggerDownload={triggerDownload} setSuccessMessage={setSuccessMessage} creativeSummary={creativeSummary}
        />
      ) : null}

      {activeTab === 'notifications' ? (
        <NotificationsTab
          notifications={notifications} isLoading={isLoading} loadWorkspace={loadWorkspace}
        />
      ) : null}


      {isFetchWebsiteModalOpen ? (
        <div className="fetch-modal-overlay" role="dialog" aria-modal="true" aria-label="Fetch details from website">
          <div className="fetch-modal-card">
            <div className="fetch-modal-head">
