                <span>Name</span>
                <input
                  value={brandProfile.avatar_profile?.name ?? ''}
                  onChange={(event) =>
                    setBrandProfile((current) => ({
                      ...current,
                      avatar_profile: {
                        ...(current.avatar_profile ?? defaultAvatarProfile()),
                        mode: 'custom',
                        name: event.target.value,
