                    }))
                  }
                />
              </label>
              <label>
                <span>Location</span>
                <input
                  value={brandProfile.avatar_profile?.location ?? ''}
                  onChange={(event) =>
                    setBrandProfile((current) => ({
                      ...current,
                      avatar_profile: {
                        ...(current.avatar_profile ?? defaultAvatarProfile()),
                        mode: 'custom',
                        location: event.target.value,
